    function recordLocal(bytes32 id)
        internal
        view
        returns (R.FreshRecoveryPolicy memory, bytes32, uint64, bytes32)
    {
        Entry storage e = store().entries[id];
        return (e.policy, e.policyHash, e.revision, e.lastActionId);
