// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamMintGateValidator.sol";
import "../../interfaces/stream/mint/IStreamERC20OfferGate.sol";

/// @notice Dedicated, bounded offer-gate dispatch with a canonical quantity-one result.
library StreamERC20OfferGateValidation {
    error InvalidERC20OfferGate();

    function validate(
        IStreamMintManager.MintBatch calldata batch,
        StreamERC20OfferMintTypes.GateData memory d,
        IStreamMintManager.MintGateConfig memory gate,
        address registry
    ) public view returns (StreamMintOperationIdentity.MintAuthorization memory a) {
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(gate, IERC165(registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(gate))) {
            revert InvalidERC20OfferGate();
        }
        a.authorizationId = batch.authorizationId;
        a.authorizer = batch.authorizer;
        a.authorizerKind = IStreamMintManager.AuthorizerKind(d.buyerSignature.kind);
        a.maxQuantity = 1;
        a.nullifiers = new bytes32[](0);
        if (gate.gate == address(0)) return a;

        bytes memory input = abi.encodeCall(
            IStreamERC20OfferGate.validateERC20OfferBatch, (address(this), msg.sender, batch, d)
        );
        uint256 cap = IStreamGasParameterHost(address(this))
            .gasParameter(keccak256("6529STREAM_GGP_MINT_GATE_GAS_LIMIT"));
        if (gate.gateGasLimit > cap) cap = gate.gateGasLimit;
        uint256 required = cap + (cap + 62) / 63 + 40_000;
        if (gasleft() < required) {
            revert StreamMintGateValidator.MintGateInsufficientGas(gasleft(), required);
        }
        // Empty nullifiers make the full dynamic GateResult exactly eight words.
        bytes memory raw = new bytes(256);
        bool ok;
        uint256 size;
        address target = gate.gate;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(raw, 32), 256)
            size := returndatasize()
        }
        if (!ok || size != 256) revert InvalidERC20OfferGate();
        uint256 outerOffset;
        uint256 nullifierOffset;
        uint256 count;
        assembly ("memory-safe") {
            outerOffset := mload(add(raw, 32))
            nullifierOffset := mload(add(raw, 96))
            count := mload(add(raw, 256))
        }
        if (outerOffset != 32 || nullifierOffset != 192 || count != 0) {
            revert InvalidERC20OfferGate();
        }
        IStreamMintGate.GateResult memory result = abi.decode(raw, (IStreamMintGate.GateResult));
        if (
            keccak256(raw) != keccak256(abi.encode(result))
                || result.authorizationId != a.authorizationId || result.authorizer != a.authorizer
                || result.authorizerKind != uint8(a.authorizerKind) || result.maxQuantity != 1
                || result.gateHash == 0
        ) revert InvalidERC20OfferGate();
        a.gateHash = result.gateHash;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { IStreamMintManager } from "../../interfaces/stream/mint/IStreamMintManager.sol";
import { IStreamMintReads } from "../../interfaces/stream/mint/IStreamMintReads.sol";
import {
    StreamERC20OfferMintTypes as Offer
} from "../../interfaces/stream/mint/StreamERC20OfferMintTypes.sol";
import {
    StreamPrivateSaleTypes as Sales
} from "../../interfaces/stream/mint/StreamPrivateSaleTypes.sol";
import { StreamMintTicketHash } from "./StreamMintTicketHash.sol";
import {
    StreamPreparedNativeContentHash as ContentHash
} from "./StreamPreparedNativeContentHash.sol";
import { StreamPrivateSaleHash } from "./StreamPrivateSaleHash.sol";

/// @notice Canonical full-payload validation and digests for one direct-to-buyer ERC20 offer mint.
/// @dev Signature authority, delegation, replay consumption and payment effects remain with callers.
library StreamERC20OfferHash {
    error InvalidERC20Offer();

    bytes32 private constant _PRIMARY_SALE = keccak256("PRIMARY_SALE");
    bytes32 private constant _RECIPIENTS = keccak256("6529STREAM_MINT_BATCH_RECIPIENTS_V1");
    bytes32 private constant _BENEFICIARIES = keccak256("6529STREAM_MINT_BATCH_BENEFICIARIES_V1");
    bytes32 private constant _TOKEN_DATA = keccak256("6529STREAM_MINT_BATCH_TOKEN_DATA_V1");
    bytes32 private constant _COMMITMENTS = keccak256("6529STREAM_MINT_BATCH_COMMITMENTS_V1");

    /// @notice Validate the complete original seller and buyer presentation and return both
    /// full Sales EIP-712 digests. The buyer digest is the Manager ticket replay authority.
    function validate(
        address manager,
        address house,
        IStreamMintManager.MintBatch calldata batch,
        Offer.GateData memory d
    ) public view returns (bytes32 sellerDigest, bytes32 offerDigest) {
        Sales.SaleAuthorization memory authorization = d.authorization;
        Sales.SaleOffer memory offer = d.offer;
        sellerDigest = StreamPrivateSaleHash.digest(
            block.chainid, house, StreamPrivateSaleHash.authorizationBody(authorization)
        );
        offerDigest = StreamPrivateSaleHash.digest(
            block.chainid, house, StreamPrivateSaleHash.offerBody(offer)
        );
        _requireOriginal(manager, house, d, authorization, offer);
        _requireBatch(house, batch, d, authorization, offer, sellerDigest, offerDigest);
    }

    function _requireOriginal(
        address manager,
        address house,
        Offer.GateData memory d,
        Sales.SaleAuthorization memory authorization,
        Sales.SaleOffer memory offer
    ) private view {
        if (
            manager == address(0) || house == address(0) || d.executor == address(0)
                || offer.buyer == address(0) || offer.buyer == house
                || authorization.chainId != block.chainid || offer.chainId != block.chainid
                || authorization.saleAdapter != house || offer.saleAdapter != house
                || authorization.mintManager != manager
                || offer.core != address(IStreamMintReads(manager).core())
                || authorization.collectionId == 0
                || authorization.collectionId != offer.collectionId || authorization.phaseId == 0
                || authorization.saleId == 0 || authorization.saleKind != 6
                || authorization.revenueClass != _PRIMARY_SALE
                || authorization.expectedPrimaryPolicyHash == 0
                || authorization.primaryPolicyMode != 0 || authorization.payer != offer.buyer
                || authorization.executor != d.executor || authorization.asset == address(0)
                || authorization.asset != offer.asset || authorization.unitPrice == 0
                || authorization.unitPrice != offer.price || authorization.quantity != 1
                || authorization.contentSelectionHash != offer.contentSelectionHash
                || authorization.policyHash == 0 || authorization.nonce == 0
                || authorization.deadline < block.timestamp || authorization.finalizeBy != 0
                || offer.tokenId != 0 || offer.nonce == 0 || offer.deadline < block.timestamp
                || offer.finalizeBy != 0
        ) revert InvalidERC20Offer();
    }

    function _requireBatch(
        address house,
        IStreamMintManager.MintBatch calldata batch,
        Offer.GateData memory d,
        Sales.SaleAuthorization memory authorization,
        Sales.SaleOffer memory offer,
        bytes32 sellerDigest,
        bytes32 offerDigest
    ) private view {
        if (
            batch.collectionId != offer.collectionId
                || batch.collectionId != authorization.collectionId
                || batch.phaseId != authorization.phaseId || batch.payer != offer.buyer
                || batch.authorizer != d.buyerSignature.authorizer
                || d.buyerSignature.authorizer == address(0)
                || (d.buyerSignature.kind != 1 && d.buyerSignature.kind != 2)
                || batch.expectedPolicyHash != authorization.policyHash
                || batch.authorizationId != StreamMintTicketHash.authorizationId(offerDigest)
                || batch.initialRecipients.length != 1 || batch.beneficiaries.length != 1
                || batch.tokenData.length != 1 || batch.mintCommitments.length != 1
                || batch.initialRecipients[0] != offer.buyer
                || batch.beneficiaries[0] != offer.buyer || batch.mintCommitments[0] == 0
                || authorization.initialRecipientsHash
                    != keccak256(abi.encode(_RECIPIENTS, batch.initialRecipients))
                || authorization.beneficiariesHash
                    != keccak256(abi.encode(_BENEFICIARIES, batch.beneficiaries))
                || authorization.tokenDataArrayHash
                    != keccak256(abi.encode(_TOKEN_DATA, batch.tokenData))
                || authorization.mintCommitmentsHash
                    != keccak256(abi.encode(_COMMITMENTS, batch.mintCommitments))
        ) revert InvalidERC20Offer();
        _requireContent(house, batch, d, authorization, sellerDigest);
    }

    function _requireContent(
        address house,
        IStreamMintManager.MintBatch calldata batch,
        Offer.GateData memory d,
        Sales.SaleAuthorization memory authorization,
        bytes32 sellerDigest
    ) private view {
        if (authorization.contentSelectionHash == 0) {
            if (
                d.selection.contentId != 0 || d.selection.tokenDataHash != 0
                    || d.selection.proof.length != 0 || sellerDigest == 0
                    || batch.contextHash != sellerDigest
            ) revert InvalidERC20Offer();
            return;
        }
        if (
            d.selection.tokenDataHash == 0
                || d.selection.tokenDataHash != keccak256(batch.tokenData[0])
                || batch.contextHash
                    != ContentHash.context(
                        block.chainid, house, authorization.saleId, d.selection.contentId
                    )
                || authorization.contentSelectionHash
                    != ContentHash.leaf(
                        block.chainid,
                        house,
                        authorization.saleId,
                        d.selection.contentId,
                        d.selection.tokenDataHash
                    )
        ) revert InvalidERC20Offer();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/mint/IStreamERC20OfferGate.sol";
import "./StreamERC20OfferHash.sol";
import "./StreamPreparedNativeContentHash.sol";
import "./StreamMintGateValidator.sol";
import "../../vendor/openzeppelin/MerkleProof.sol";

/// @notice Independent original leaf/bytes correspondence and actual phase/counter selection.
library StreamERC20OfferReads {
    error InvalidERC20OfferContent();

    function requirePublication(
        address manager,
        address registry,
        address house,
        uint256 collection,
        bytes32 phase,
        bytes32 saleId,
        bytes32 root
    )
        public
        view
        returns (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        )
    {
        IStreamMintManager m = IStreamMintManager(manager);
        g = m.phaseGate(collection, phase);
        if (g.gate == address(0) || g.gate.codehash != g.gateCodehash || root == 0) {
            revert InvalidERC20OfferContent();
        }
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(g, IERC165(registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(g))) {
            revert InvalidERC20OfferContent();
        }
        IStreamERC20OfferGate gate = IStreamERC20OfferGate(g.gate);
        p = gate.publication();
        if (
            !gate.supportsInterface(type(IStreamERC20OfferGate).interfaceId)
                || gate.offerPurchaseVersion()
                    != keccak256("6529STREAM_ERC20_PRIMARY_OFFER_GATE_V1")
                || gate.gateConfigHash() != g.gateConfigHash || p.chainId != block.chainid
                || p.manager != manager || p.house != house || p.collectionId != collection
                || p.phaseId != phase || p.saleId != saleId || p.manifestRoot != root
                || p.manifestHash == 0 || p.counterId == 0 || gate.itemCount() == 0
        ) revert InvalidERC20OfferContent();
        if (
            g.gateConfigHash
                != keccak256(
                    abi.encode(
                        keccak256("6529STREAM_ERC20_PRIMARY_OFFER_GATE_V1"),
                        p,
                        manager.codehash,
                        house.codehash
                    )
                )
        ) revert InvalidERC20OfferContent();
        requireManifest(gate, p);
        (bool exists, IStreamMintManager.MintPhaseConfig memory config) = m.phase(collection, phase);
        IStreamMintManager.MintCounterConfig memory counter =
            m.counterConfig(collection, phase, p.counterId);
        bytes32[] memory ids = m.phaseCounterIds(collection, phase);
        bool found;
        for (uint256 n; n < ids.length; ++n) {
            if (ids[n] == p.counterId) found = true;
        }
        if (
            !exists || config.paused || config.maxBatchQuantity != 1
                || !m.phaseExecutor(collection, phase, house) || !found || !counter.enabled
                || counter.keyMode != IStreamMintManager.CounterKeyMode.CONTEXT
                || counter.capMode != IStreamMintLedger.CounterCapMode.STATIC
                || counter.deltaMode != IStreamMintLedger.CounterDeltaMode.STATIC
                || counter.staticCap != 1 || counter.staticIncrement != 1
                || counter.counterConfigHash == 0
        ) revert InvalidERC20OfferContent();
    }

    function requireManifest(
        IStreamERC20OfferGate gate,
        StreamPreparedNativeContentTypes.Publication memory p
    ) private view {
        bytes memory raw = gate.manifestBytes();
        StreamPreparedNativeContentTypes.Row[] memory rows =
            abi.decode(raw, (StreamPreparedNativeContentTypes.Row[]));
        if (
            rows.length == 0 || rows.length != gate.itemCount() || keccak256(raw) != p.manifestHash
                || keccak256(abi.encode(rows)) != p.manifestHash
        ) revert InvalidERC20OfferContent();
        bytes32[] memory level = new bytes32[](rows.length);
        for (uint256 n; n < rows.length; ++n) {
            if (
                (n != 0 && rows[n - 1].contentId >= rows[n].contentId) || rows[n].tokenDataHash == 0
                    || bytes(rows[n].previewURI).length == 0
            ) revert InvalidERC20OfferContent();
            level[n] = StreamPreparedNativeContentHash.leaf(
                p.chainId, p.house, p.saleId, rows[n].contentId, rows[n].tokenDataHash
            );
        }
        uint256 width = rows.length;
        while (width > 1) {
            uint256 next;
            for (uint256 n; n < width; n += 2) {
                bytes32 a = level[n];
                if (n + 1 == width) {
                    level[next] = a;
                } else {
                    bytes32 b = level[n + 1];
                    level[next] = a < b
                        ? keccak256(abi.encodePacked(a, b))
                        : keccak256(abi.encodePacked(b, a));
                }
                ++next;
            }
            width = next;
        }
        if (level[0] != p.manifestRoot) revert InvalidERC20OfferContent();
    }

    function requireBatch(
        address manager,
        address registry,
        address house,
        IStreamMintManager.MintBatch calldata b,
        StreamERC20OfferMintTypes.GateData memory d
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        if (b.tokenData.length != 1 || b.tokenData[0].length > 8192) {
            revert InvalidERC20OfferContent();
        }
        (bytes32 sellerDigest,) = StreamERC20OfferHash.validate(manager, house, b, d);
        IStreamMintManager.MintGateConfig memory selected =
            IStreamMintManager(manager).phaseGate(b.collectionId, b.phaseId);
        if (selected.gate == address(0)) {
            _requireNoGate(selected);
            if (
                d.selection.contentId != 0 || d.selection.tokenDataHash != 0
                    || d.selection.proof.length != 0 || d.authorization.contentSelectionHash != 0
                    || d.offer.contentSelectionHash != 0 || b.contextHash != sellerDigest
            ) revert InvalidERC20OfferContent();
            c.tokenDataHash = keccak256(b.tokenData[0]);
            c.contextHash = sellerDigest;
            return c;
        }
        if (d.selection.tokenDataHash != keccak256(b.tokenData[0])) {
            revert InvalidERC20OfferContent();
        }
        StreamPreparedNativeContentTypes.Publication memory declared =
            IStreamERC20OfferGate(selected.gate).publication();
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            manager,
            registry,
            house,
            b.collectionId,
            b.phaseId,
            d.authorization.saleId,
            declared.manifestRoot
        );
        c.gate = g.gate;
        c.gateCodeHash = g.gateCodehash;
        c.gateConfigHash = g.gateConfigHash;
        c.manifestRoot = p.manifestRoot;
        c.manifestHash = p.manifestHash;
        c.counterId = p.counterId;
        c.contentId = d.selection.contentId;
        c.tokenDataHash = d.selection.tokenDataHash;
        c.contentLeaf = StreamPreparedNativeContentHash.leaf(
            block.chainid, house, p.saleId, c.contentId, c.tokenDataHash
        );
        c.contextHash =
            StreamPreparedNativeContentHash.context(block.chainid, house, p.saleId, c.contentId);
        if (
            b.contextHash != c.contextHash || c.contentLeaf != d.authorization.contentSelectionHash
                || c.contentLeaf != d.offer.contentSelectionHash
                || !MerkleProof.verify(d.selection.proof, c.manifestRoot, c.contentLeaf)
        ) revert InvalidERC20OfferContent();
    }

    function _requireNoGate(IStreamMintManager.MintGateConfig memory g) private pure {
        IStreamMintManager.MintGateConfig memory empty;
        if (keccak256(abi.encode(g)) != keccak256(abi.encode(empty))) {
            revert InvalidERC20OfferContent();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamERC20OfferHash.sol";
import "../../interfaces/stream/mint/StreamERC20OfferMintTypes.sol";
import "../../interfaces/stream/mint/StreamPreparedNativeContentTypes.sol";
import "../../interfaces/stream/mint/StreamPrivateSaleTypes.sol";
import "../../interfaces/stream/mint/IStreamPrivateSaleAdapter.sol";
import "../../interfaces/stream/mint/IStreamNativeRefundDelegatedClaims.sol";
import "./StreamMintTranscriptTypes.sol";
import "./StreamImmediateSaleReveal.sol";
import "./StreamUniversalSaleRights.sol";
import "../revenue/StreamPreparedNativeSettlementAdmission.sol";
import "../revenue/StreamPrimarySettlementHash.sol";
import "../revenue/StreamPrimarySettlementRights.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeMint.sol";
import { IStreamERC20OfferSale } from "../../interfaces/stream/mint/IStreamERC20OfferMint.sol";

/// @notice Exact, already-funded order-one receipt required before the offer mint consumes state.
/// @dev Runs in Manager context. Signature/delegation admission and the operation transcript are
/// supplied by the Manager's offer path; this join grants no payment or prepared-mint authority.
library StreamERC20OfferReceipt {
    error InvalidERC20OfferReceipt();
    error ERC20OfferReceiptReadFailed(address target, bytes4 selector);
    error ERC20OfferNativeFeeRequired(uint256 amount);

    // ABI-equivalent to the carrier's Acceptance. Kept local to avoid coupling Manager to a
    // sale implementation. The single dynamic tuple wrapper is part of saleExecutionHash.
    struct SelectionWire {
        StreamPreparedNativeContentTypes.Selection content;
        bytes tokenData;
        bytes32 mintCommitment;
        uint256 executionNonce;
    }

    struct AcceptanceWire {
        StreamPrivateSaleTypes.SaleOffer offer;
        IStreamPrivateSaleAdapter.Signature buyerProof;
        StreamPrivateSaleTypes.SaleAuthorization authorization;
        IStreamPrivateSaleAdapter.Signature sellerProof;
        SelectionWire selection;
        IStreamNativeRefundDelegatedClaims.DelegationWitness signerDelegation;
        IStreamNativeRefundDelegatedClaims.DelegationWitness executorDelegation;
    }

    function requireReceipt(
        address core,
        address registry,
        address recorder,
        bytes32 recorderCodeHash,
        IStreamMintManager.MintBatch calldata batch,
        StreamERC20OfferMintTypes.GateData calldata d,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate calldata c,
        StreamMintTranscriptTypes.OperationTranscript memory t
    ) public view {
        _requireReceipt(core, registry, recorder, recorderCodeHash, batch, d, c, t);
    }

    /// @notice Decode only the original candidate's 34 static ABI words inside the linked worker.
    /// @dev The Manager's external typed ABI remains unchanged; no alternate candidate wire exists.
    function requireReceiptEncoded(
        address core,
        address registry,
        address recorder,
        bytes32 recorderCodeHash,
        IStreamMintManager.MintBatch calldata batch,
        StreamERC20OfferMintTypes.GateData calldata d,
        bytes calldata encodedCandidate,
        StreamMintTranscriptTypes.OperationTranscript memory t
    ) public view {
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory
            c = _decodeCandidate(encodedCandidate);
        _requireReceipt(core, registry, recorder, recorderCodeHash, batch, d, c, t);
    }

    /// @notice Decode the frozen execute selector's complete argument buffer in the linked worker.
    /// @dev The first two words point to batch/GateData tails after the 34-word static candidate.
    /// Decoding two dynamic types retains those original offsets; this does not redefine the ABI.
    function requireReceiptArguments(
        address core,
        address registry,
        address recorder,
        bytes32 recorderCodeHash,
        IStreamMintManager.MintBatch calldata batch,
        bytes calldata arguments,
        StreamMintTranscriptTypes.OperationTranscript memory t
    ) public view {
        if (arguments.length < 36 * 32) {
            revert InvalidERC20OfferReceipt();
        }
        (
            IStreamMintManager.MintBatch memory decodedBatch,
            StreamERC20OfferMintTypes.GateData memory d
        ) = abi.decode(
            arguments, (IStreamMintManager.MintBatch, StreamERC20OfferMintTypes.GateData)
        );
        if (keccak256(abi.encode(decodedBatch)) != keccak256(abi.encode(batch))) {
            revert InvalidERC20OfferReceipt();
        }
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c =
            _decodeCandidate(arguments[64:1152]);
        _requireReceipt(core, registry, recorder, recorderCodeHash, batch, d, c, t);
    }

    function _decodeCandidate(bytes calldata encodedCandidate)
        private
        pure
        returns (StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c)
    {
        if (encodedCandidate.length != 34 * 32) revert InvalidERC20OfferReceipt();
        c = abi.decode(encodedCandidate, (StreamPrimarySettlementTypes.ERC20SettlementCandidate));
        if (keccak256(encodedCandidate) != keccak256(abi.encode(c))) {
            revert InvalidERC20OfferReceipt();
        }
    }

    function _requireReceipt(
        address core,
        address registry,
        address recorder,
        bytes32 recorderCodeHash,
        IStreamMintManager.MintBatch calldata batch,
        StreamERC20OfferMintTypes.GateData memory d,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamMintTranscriptTypes.OperationTranscript memory t
    ) private view {
        _fields(core, batch, d, c, t);
        _saleFacts(batch, c);
        _bindings(core, registry, recorder, recorderCodeHash, c);
        _rights(recorder, c);
        _stored(recorder, c);
        IStreamImmediateSaleReveal.RevealQuote memory q =
            StreamImmediateSaleReveal.quote(core, batch.collectionId);
        if (q.policy.revealFeePerTokenWei != 0) {
            revert ERC20OfferNativeFeeRequired(q.policy.revealFeePerTokenWei);
        }
    }

    function _saleFacts(
        IStreamMintManager.MintBatch calldata batch,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) private view {
        bytes memory raw = _read(
            msg.sender,
            abi.encodeCall(
                IStreamERC20OfferSale.primaryOfferSettlementBinding, (c.sale.settlementId)
            ),
            96
        );
        (uint256 nonce, address poster, bytes32 configHash) =
            abi.decode(raw, (uint256, address, bytes32));
        if (
            keccak256(raw) != keccak256(abi.encode(nonce, poster, configHash))
                || nonce != c.sale.saleNonce || poster != c.sale.poster || configHash == 0
        ) revert InvalidERC20OfferReceipt();
        raw = _read(
            msg.sender,
            abi.encodeCall(
                IStreamERC20OfferSale.primaryOfferAuthorizationBinding, (c.sale.settlementId)
            ),
            160
        );
        (uint256 collection, bytes32 phase, address seller, uint8 kind, bytes32 signerConfig) =
            abi.decode(raw, (uint256, bytes32, address, uint8, bytes32));
        if (
            keccak256(raw) != keccak256(abi.encode(collection, phase, seller, kind, signerConfig))
                || collection != batch.collectionId || phase != batch.phaseId
                || seller == address(0) || (kind != 1 && kind != 2) || signerConfig != configHash
        ) revert InvalidERC20OfferReceipt();
    }

    function _fields(
        address core,
        IStreamMintManager.MintBatch calldata b,
        StreamERC20OfferMintTypes.GateData memory d,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamMintTranscriptTypes.OperationTranscript memory t
    ) private view {
        (bytes32 sellerDigest,) = StreamERC20OfferHash.validate(address(this), msg.sender, b, d);
        if (
            c.saleAdapter != msg.sender || c.mintManager != address(this) || d.offer.core != core
                || c.executor != d.executor || c.sale.settlementId != d.authorization.saleId
                || c.sale.revenueClass != keccak256("PRIMARY_SALE") || c.sale.policyMode != 0
                || c.sale.collectionId != b.collectionId || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer != b.payer
                || c.sale.beneficiary != d.offer.buyer || c.sale.amount != d.offer.price
                || c.sale.amount == 0 || c.asset == address(0) || c.asset != d.offer.asset
                || c.sale.expectedPrimaryPolicyHash != d.authorization.expectedPrimaryPolicyHash
                || c.sale.expectedPrimaryPolicyHash == 0 || c.orchestrationOrder != 1
                || c.executionBinding.authorityMode != 1 || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest != sellerDigest
                || c.executionBinding.executionId != StreamPrimarySettlementHash.executionId(c)
                || t.quantity != 1 || t.operationIds.length != 1 || t.operationRoot == 0
                || t.operationIds[0] == 0 || c.operationIdentityCommitment != t.operationRoot
                || c.operationId != t.operationIds[0] || c.currentPolicyHash != t.currentPolicyHash
                || c.boundPolicyHash != t.boundPolicyHash || c.currentPolicyHash == 0
                || c.boundPolicyHash != b.expectedPolicyHash
                || t.authorization.authorizationId != b.authorizationId
                || t.authorization.authorizer != b.authorizer
                || uint8(t.authorization.authorizerKind) != d.buyerSignature.kind
        ) revert InvalidERC20OfferReceipt();
        AcceptanceWire memory a = AcceptanceWire(
            d.offer,
            d.buyerSignature,
            d.authorization,
            d.sellerSignature,
            SelectionWire(
                d.selection, b.tokenData[0], b.mintCommitments[0], c.executionBinding.executionNonce
            ),
            d.buyerDelegation,
            d.executorDelegation
        );
        if (c.saleExecutionHash != keccak256(abi.encode(a))) revert InvalidERC20OfferReceipt();
    }

    function _bindings(
        address core,
        address registry,
        address recorder,
        bytes32 recorderHash,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) private view {
        if (!StreamSettlementAdmission.isContract(recorder) || recorder.codehash != recorderHash) {
            revert InvalidERC20OfferReceipt();
        }
        bytes memory raw = _read(
            address(this), abi.encodeCall(IStreamPreparedNativeMint.preparedNativeRecorder, ()), 128
        );
        (address selected, bytes32 selectedHash, uint64 boundAt, uint64 revision) =
            abi.decode(raw, (address, bytes32, uint64, uint64));
        if (
            selected != recorder || selectedHash != recorderHash
                || keccak256(raw)
                    != keccak256(abi.encode(selected, selectedHash, boundAt, revision))
        ) revert InvalidERC20OfferReceipt();
        StreamPreparedNativeSettlementAdmission.requireRecorder(
            registry, recorder, boundAt, revision
        );
        StreamSettlementAdmission.requireRegistry(
            core,
            bytes32(_word(recorder, "coreCodeHash()")),
            registry,
            bytes32(_word(recorder, "moduleRegistryCodeHash()"))
        );
        address payment = c.lifecycleBinding.paymentAdapter;
        address resolver = _address(recorder, "revenueResolver()");
        if (
            _address(recorder, "core()") != core
                || _address(recorder, "moduleRegistry()") != registry
                || _address(msg.sender, "primarySaleSettlement()") != recorder
                || bytes32(_word(msg.sender, "settlementCodeHash()")) != recorderHash
                || _address(msg.sender, "core()") != core
                || _address(msg.sender, "moduleRegistry()") != registry
                || _address(msg.sender, "mintManager()") != address(this)
                || _address(msg.sender, "revenueResolver()") != resolver
                || _address(payment, "primarySaleSettlement()") != recorder
                || bytes32(_word(payment, "settlementCodeHash()")) != recorderHash
                || _address(payment, "core()") != core
                || _address(payment, "moduleRegistry()") != registry
                || _address(payment, "revenueResolver()") != resolver || c.sale.payer == recorder
                || c.sale.payer == payment || c.sale.payer == c.rights.wallet
                || c.sale.payer == _address(recorder, "revenueEscrow()")
        ) revert InvalidERC20OfferReceipt();
        StreamSettlementAdmission.requireAdmission(registry, payment, c);
    }

    function _rights(
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) private view {
        address resolver = _address(recorder, "revenueResolver()");
        address factory = _address(recorder, "splitFactory()");
        address assets = _address(recorder, "assetPolicyRegistry()");
        if (
            resolver.codehash != bytes32(_word(recorder, "resolverCodeHash()"))
                || factory.codehash != bytes32(_word(recorder, "factoryCodeHash()"))
                || assets.codehash != bytes32(_word(recorder, "assetRegistryCodeHash()"))
                || !StreamSettlementAdmission.isContract(c.asset) || c.rights.templateId != 0
        ) revert InvalidERC20OfferReceipt();
        StreamSaleTemplate.Selection memory rights = StreamUniversalSaleRights.rights(
            IStreamRevenueResolver(resolver), IStreamSplitFactory(factory), c.sale.collectionId
        );
        if (
            keccak256(abi.encode(rights)) != keccak256(abi.encode(c.rights))
                || StreamSaleTemplate.policyHash(
                        IStreamRevenueResolver(resolver), c.sale.collectionId, rights
                    ) != c.sale.expectedPrimaryPolicyHash
        ) revert InvalidERC20OfferReceipt();
        StreamPrimarySettlementRights.requireWallet(
            StreamPrimarySettlementRights.Context(
                IStreamRevenueResolver(resolver),
                IStreamSplitFactory(factory),
                bytes32(_word(recorder, "walletCodeHash()"))
            ),
            rights
        );
        uint256 cap = abi.decode(
            _read(
                factory,
                abi.encodeCall(
                    IStreamGasParameterHost.gasParameter,
                    (keccak256("6529STREAM_GGP_ASSET_POLICY_GAS_LIMIT"))
                ),
                32
            ),
            (uint256)
        );
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 40_000) {
            revert InvalidERC20OfferReceipt();
        }
        bytes memory data = abi.encodeCall(IStreamAssetPolicyRegistry.assetStatus, (c.asset));
        uint256 value;
        uint256 size;
        bool ok;
        assembly ("memory-safe") {
            ok := staticcall(cap, assets, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            value := mload(0)
        }
        if (!ok || size != 32 || value != 1) revert InvalidERC20OfferReceipt();
    }

    function _stored(
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) private view {
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
                recorder, msg.sender, c.executionBinding.executionId
            );
        if (
            abi.decode(
                    _read(
                        recorder,
                        abi.encodeCall(IStreamPrimarySaleSettlement.settlementConsumed, (key)),
                        32
                    ),
                    (uint256)
                ) != 1
        ) {
            revert InvalidERC20OfferReceipt();
        }
        bytes memory raw = _read(
            recorder, abi.encodeCall(IStreamPrimarySaleSettlement.settlementResult, (key)), 384
        );
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r =
            abi.decode(raw, (StreamPrimarySettlementTypes.PrimarySettlementResult));
        if (
            keccak256(raw) != keccak256(abi.encode(r))
                || r.candidateCommitment
                    != StreamPrimarySettlementHash.candidateCommitment(
                        c.lifecycleBinding.paymentAdapter, recorder, c
                    ) || r.settlementKey != key || r.profileId != c.rights.profileId
                || r.wallet != c.rights.wallet || r.asset != c.asset || r.amount != c.sale.amount
                || r.executor != c.executor || r.executionId != c.executionBinding.executionId
                || r.operationIdentityCommitment != c.operationIdentityCommitment
                || r.currentPolicyHash != c.currentPolicyHash
                || r.boundPolicyHash != c.boundPolicyHash
        ) revert InvalidERC20OfferReceipt();
    }

    function _address(address target, string memory signature) private view returns (address) {
        uint256 value = _word(target, signature);
        if (value == 0 || value > type(uint160).max) revert InvalidERC20OfferReceipt();
        return address(uint160(value));
    }

    function _word(address target, string memory signature) private view returns (uint256) {
        return abi.decode(_read(target, abi.encodeWithSignature(signature), 32), (uint256));
    }

    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory raw)
    {
        raw = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), add(raw, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert ERC20OfferReceiptReadFailed(target, bytes4(data));
    }
}

