// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintPhaseFreeze.sol";
import "../../interfaces/stream/mint/IStreamMintLedgerPhaseFreeze.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";
import "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";

interface IStreamMintPhaseFreezeBinding {
    function core() external view returns (address);
    function mintLedger() external view returns (address);
    function governanceAuthority() external view returns (address);
    function owner() external view returns (address);
}

/// @notice Fixed Manager worker for the optional, canonical Ledger-backed freeze.
/// @dev Only the host owns entrypoint guards and executor storage references.
library StreamMintPhaseFreezeControl {
    bytes32 private constant SCOPE = keccak256("6529STREAM_MINT_PHASE_FREEZE_SCOPE_V1");
    bytes32 private constant STATE = keccak256("6529STREAM_MINT_PHASE_FREEZE_STATE_V1");

    event MintPhaseFrozen(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bool frozen,
        bytes32 policyHash
    );

    function frozen(address ledger, address manager, uint256 collectionId, bytes32 phaseId)
        public
        view
        returns (bool)
    {
        bytes memory support = _read(
            ledger,
            abi.encodeCall(
                IERC165.supportsInterface, (type(IStreamMintLedgerPhaseFreeze).interfaceId)
            ),
            32
        );
        uint256 supported = abi.decode(support, (uint256));
        if (supported > 1) revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
        if (supported == 0) return false;
        bytes memory raw = _read(
            ledger,
            abi.encodeCall(
                IStreamMintLedgerPhaseFreeze.phaseFreeze, (manager, collectionId, phaseId)
            ),
            64
        );
        IStreamMintLedgerPhaseFreeze.PhaseFreeze memory record =
            abi.decode(raw, (IStreamMintLedgerPhaseFreeze.PhaseFreeze));
        return record.configurationHash != 0;
    }

    function transition(address manager, uint256 collectionId, bytes32 phaseId)
        public
        view
        returns (bytes32 scope, bytes32 oldHash, bytes32 newHash)
    {
        IStreamMintPhaseFreezeBinding host = IStreamMintPhaseFreezeBinding(manager);
        bytes32 policyHash = IStreamMintManager(manager).phasePolicyHash(collectionId, phaseId);
        if (policyHash == 0) {
            revert IStreamMintManager.MintPhaseDoesNotExist(collectionId, phaseId);
        }
        scope = keccak256(
            abi.encode(
                SCOPE, block.chainid, host.core(), manager, host.mintLedger(), collectionId, phaseId
            )
        );
        oldHash = keccak256(abi.encode(STATE, scope, false, policyHash));
        newHash = keccak256(abi.encode(STATE, scope, true, policyHash));
    }

    /// @dev The original Manager facade checks onlyOwner, configured phase and nonReentrant.
    function freeze(uint256 collectionId, bytes32 phaseId) external {
        IStreamMintPhaseFreezeBinding host = IStreamMintPhaseFreezeBinding(address(this));
        address ledger = host.mintLedger();
        if (frozen(ledger, address(this), collectionId, phaseId)) {
            revert IStreamMintPhaseFreeze.MintPhaseAlreadyFrozen(collectionId, phaseId);
        }
        address authority = host.governanceAuthority();
        if (msg.sender != authority || host.owner() != authority || authority.code.length == 0) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeGovernanceInvalid();
        }
        (bytes32 scope, bytes32 oldHash, bytes32 newHash) =
            transition(address(this), collectionId, phaseId);
        bytes memory raw = _read(
            authority, abi.encodeCall(IStreamGovernedParameterAuthority.currentAction, ()), 192
        );
        (bool executing, bytes32 id, uint8 cls, bytes32 actualScope, bytes32 old_, bytes32 new_) =
            abi.decode(raw, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (
            !executing || id == 0 || cls != 2 || actualScope != scope || old_ != oldHash
                || new_ != newHash
                || keccak256(raw)
                    != keccak256(abi.encode(executing, id, cls, actualScope, old_, new_))
        ) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeGovernanceInvalid();
        }
        bytes32 policyHash =
            IStreamMintManager(address(this)).phasePolicyHash(collectionId, phaseId);
        IStreamMintLedgerPhaseFreeze(ledger).freezePhase(collectionId, phaseId, policyHash);
        emit MintPhaseFrozen(1, collectionId, phaseId, true, policyHash);
    }

    /// @notice First successor configuration inherits already-frozen rights before hashing/consent.
    /// @dev The Ledger independently checks immutable terms and shrinks its executor ceiling at
    /// registration. Failed configuration rolls these storage writes back with the whole call.
    function inheritExecutors(
        mapping(address => bool) storage authorized,
        address[] storage executors,
        mapping(address => uint256) storage indexPlusOne,
        address ledger,
        uint256 collectionId,
        bytes32 phaseId
    ) external {
        if (!frozen(ledger, address(this), collectionId, phaseId)) return;
        if (executors.length != 0) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
        }
        bytes memory input = abi.encodeCall(
            IStreamMintLedgerPhaseFreeze.frozenPhaseExecutors,
            (address(this), collectionId, phaseId)
        );
        // Original Manager maximum: 64 addresses plus ABI offset and array length.
        bytes memory raw = new bytes(2112);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), ledger, add(input, 32), mload(input), add(raw, 32), 2112)
            size := returndatasize()
        }
        if (!ok || size < 64 || size > 2112) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
        }
        assembly ("memory-safe") { mstore(raw, size) }
        uint256 offset;
        uint256 count;
        assembly ("memory-safe") {
            offset := mload(add(raw, 32))
            count := mload(add(raw, 64))
        }
        if (offset != 32 || count > 64 || size != 64 + count * 32) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
        }
        address[] memory inherited = abi.decode(raw, (address[]));
        if (inherited.length > 64 || keccak256(raw) != keccak256(abi.encode(inherited))) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
        }
        for (uint256 i; i < inherited.length; ++i) {
            address executor = inherited[i];
            if (executor == address(0) || authorized[executor]) {
                revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(ledger);
            }
            authorized[executor] = true;
            executors.push(executor);
            indexPlusOne[executor] = i + 1;
        }
    }

    function _read(address target, bytes memory input, uint256 expected)
        private
        view
        returns (bytes memory output)
    {
        output = new bytes(expected);
        bool ok;
        uint256 size;
        // Targets are immutable Ledger/authority bindings, with fixed-size return copying.
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(input, 32), mload(input), add(output, 32), expected)
            size := returndatasize()
        }
        if (!ok || size != expected) {
            revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(target);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintLedgerPhaseFreeze.sol";
import "../../interfaces/stream/mint/IStreamMintPhaseFreeze.sol";
import "../../interfaces/stream/mint/IStreamMintCounterPolicy.sol";
import "../../interfaces/stream/mint/IStreamMintLedgerImport.sol";
import "../../interfaces/stream/mint/IStreamMintRoyaltyPolicy.sol";

/// @dev Existing immutable Manager bindings, outside the retained Manager compatibility ABI.
interface IStreamMintFreezeManagerBindings {
    function core() external view returns (address);
    function mintLedger() external view returns (address);
    function moduleRegistry() external view returns (address);
}

/// @notice Fixed Ledger worker for immutable phase constraints and monotonic executor rights.
/// @dev All state belongs to the Ledger. Configuration is read from the actual Manager;
/// no caller-provided configuration commitment can authorize a freeze or its inheritance.
library StreamMintPhaseFreezeState {
    struct Identity {
        uint256 collectionId;
        bytes32 phaseId;
    }

    struct Frozen {
        IStreamMintLedgerPhaseFreeze.PhaseFreeze fact;
        address[] executors;
        mapping(address => bool) allowed;
    }

    struct Progress {
        uint256 imported;
        uint256 required;
    }

    struct State {
        mapping(address => mapping(uint256 => mapping(bytes32 => Frozen))) phases;
        mapping(address => Identity[]) inventory;
        mapping(bytes32 => Progress) imports;
    }

    struct Snapshot {
        bytes32 configurationHash;
        bytes32 policyHash;
        bytes32[] counterIds;
        address[] executors;
    }

    event MintLedgerPhaseFrozen(
        uint16 schemaVersion,
        address indexed manager,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 policyHash,
        bytes32 configurationHash
    );
    event MintLedgerPhaseFreezeImported(
        bytes32 indexed importRoot,
        address indexed predecessorManager,
        address indexed successorManager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 predecessorFrozenPolicyHash,
        bytes32 successorPolicyHash,
        bytes32 configurationHash
    );

    function freeze(
        State storage s,
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash
    ) external {
        Frozen storage f = s.phases[manager][collectionId][phaseId];
        if (f.fact.configurationHash != 0) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezeInvalid(
                manager, collectionId, phaseId
            );
        }
        Snapshot memory current = _snapshot(manager, collectionId, phaseId, policyHash);
        _create(s, manager, collectionId, phaseId, current);
        emit MintLedgerPhaseFrozen(
            1, manager, collectionId, phaseId, policyHash, current.configurationHash
        );
    }

    /// @dev Called after registration and definition selection, inside the same atomic write.
    function validateRegistration(
        State storage s,
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash,
        bytes32[] calldata counterIds
    ) external {
        Frozen storage f = s.phases[manager][collectionId][phaseId];
        if (f.fact.configurationHash == 0) return;
        Snapshot memory current = _snapshot(manager, collectionId, phaseId, policyHash);
        if (
            current.configurationHash != f.fact.configurationHash
                || keccak256(abi.encode(current.counterIds)) != keccak256(abi.encode(counterIds))
        ) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                manager, collectionId, phaseId
            );
        }
        _requireSubset(f, current.executors, manager, collectionId, phaseId);
        _replaceExecutors(f, current.executors);
    }

    function captureImport(
        State storage s,
        bytes32 root,
        address predecessorLedger,
        address predecessorManager
    ) external {
        bytes memory input = abi.encodeCall(
            IERC165.supportsInterface, (type(IStreamMintLedgerPhaseFreeze).interfaceId)
        );
        bytes memory output = _read(predecessorLedger, input, 32);
        if (output.length != 32) revert IStreamMintLedgerImport.MintImportInvalid();
        uint256 supported = abi.decode(output, (uint256));
        if (supported > 1) revert IStreamMintLedgerImport.MintImportInvalid();
        if (supported == 0) return;
        output = _read(
            predecessorLedger,
            abi.encodeCall(IStreamMintLedgerPhaseFreeze.frozenPhaseCount, (predecessorManager)),
            32
        );
        if (output.length != 32) revert IStreamMintLedgerImport.MintImportInvalid();
        uint256 count = abi.decode(output, (uint256));
        if (count != 0 && predecessorLedger != address(this)) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezeLedgerMismatch(
                predecessorLedger, address(this)
            );
        }
        s.imports[root].required = count;
    }

    /// @dev A not-yet-configured successor inherits constraints first; its first registration
    /// must satisfy them. This permits complete import before Core/Artist successor admission.
    function copyImport(
        State storage s,
        bytes32 root,
        IStreamMintLedgerImport.ImportCommitment memory c,
        uint256 maxCount
    ) external {
        Progress storage progress = s.imports[root];
        uint256 end = progress.imported + maxCount;
        if (end > progress.required) end = progress.required;
        for (uint256 i = progress.imported; i < end; ++i) {
            // Nonempty freeze inventories can only enter through this same original Ledger.
            if (c.predecessorLedger != address(this)) {
                revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezeLedgerMismatch(
                    c.predecessorLedger, address(this)
                );
            }
            Identity memory identity = s.inventory[c.predecessorManager][i];
            _copyPhase(s, root, c, identity);
        }
        progress.imported = end;
    }

    function _copyPhase(
        State storage s,
        bytes32 root,
        IStreamMintLedgerImport.ImportCommitment memory c,
        Identity memory identity
    ) private {
        uint256 collectionId = identity.collectionId;
        bytes32 phaseId = identity.phaseId;
        Frozen storage previous = s.phases[c.predecessorManager][collectionId][phaseId];
        Frozen storage next = s.phases[c.successorManager][collectionId][phaseId];
        Snapshot memory current;
        bytes32 currentPolicy = IStreamMintLedger(address(this))
            .registeredPhasePolicyHash(c.successorManager, collectionId, phaseId);
        if (currentPolicy == 0) {
            current.configurationHash = previous.fact.configurationHash;
            current.executors = previous.executors;
        } else {
            current = _snapshot(c.successorManager, collectionId, phaseId, currentPolicy);
            if (current.configurationHash != previous.fact.configurationHash) {
                revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                    c.successorManager, collectionId, phaseId
                );
            }
            _requireSubset(previous, current.executors, c.successorManager, collectionId, phaseId);
        }
        if (next.fact.configurationHash == 0) {
            // Preserve the original first frozen policy as provenance across generations.
            current.policyHash = previous.fact.policyHash;
            _create(s, c.successorManager, collectionId, phaseId, current);
        } else {
            if (next.fact.configurationHash != current.configurationHash) {
                revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                    c.successorManager, collectionId, phaseId
                );
            }
            _requireSubset(next, current.executors, c.successorManager, collectionId, phaseId);
            _replaceExecutors(next, current.executors);
        }
        emit MintLedgerPhaseFreezeImported(
            root,
            c.predecessorManager,
            c.successorManager,
            collectionId,
            phaseId,
            previous.fact.policyHash,
            currentPolicy,
            previous.fact.configurationHash
        );
    }

    function _create(
        State storage s,
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        Snapshot memory current
    ) private {
        Frozen storage f = s.phases[manager][collectionId][phaseId];
        f.fact =
            IStreamMintLedgerPhaseFreeze.PhaseFreeze(current.policyHash, current.configurationHash);
        s.inventory[manager].push(Identity(collectionId, phaseId));
        _replaceExecutors(f, current.executors);
    }

    function _requireSubset(
        Frozen storage previous,
        address[] memory current,
        address manager,
        uint256 collectionId,
        bytes32 phaseId
    ) private view {
        for (uint256 i; i < current.length; ++i) {
            if (!previous.allowed[current[i]]) {
                revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                    manager, collectionId, phaseId
                );
            }
        }
    }

    function _replaceExecutors(Frozen storage f, address[] memory current) private {
        for (uint256 i; i < f.executors.length; ++i) {
            delete f.allowed[f.executors[i]];
        }
        delete f.executors;
        for (uint256 i; i < current.length; ++i) {
            f.executors.push(current[i]);
            f.allowed[current[i]] = true;
        }
    }

    function _snapshot(address manager, uint256 collectionId, bytes32 phaseId, bytes32 expected)
        private
        view
        returns (Snapshot memory result)
    {
        if (manager.code.length == 0 || collectionId == 0 || phaseId == 0 || expected == 0) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezeInvalid(
                manager, collectionId, phaseId
            );
        }
        address boundLedger =
            _address(manager, IStreamMintFreezeManagerBindings.mintLedger.selector);
        address core = _address(manager, IStreamMintFreezeManagerBindings.core.selector);
        address registry =
            _address(manager, IStreamMintFreezeManagerBindings.moduleRegistry.selector);
        if (boundLedger != address(this) || core.code.length == 0 || registry.code.length == 0) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezeInvalid(
                manager, collectionId, phaseId
            );
        }
        (bool exists, IStreamMintManager.MintPhaseConfig memory config) = abi.decode(
            _exact(manager, abi.encodeCall(IStreamMintManager.phase, (collectionId, phaseId)), 224),
            (bool, IStreamMintManager.MintPhaseConfig)
        );
        result.policyHash = abi.decode(
            _exact(
                manager,
                abi.encodeCall(IStreamMintManager.phasePolicyHash, (collectionId, phaseId)),
                32
            ),
            (bytes32)
        );
        if (!exists || result.policyHash != expected) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                manager, collectionId, phaseId
            );
        }
        config.paused = false;
        (bytes32 royaltyBranch, IStreamMintRoyaltyPolicy.Policy memory royalty) =
            _royalty(manager, collectionId, phaseId, config);
        IStreamMintManager.MintGateConfig memory gate = abi.decode(
            _exact(
                manager, abi.encodeCall(IStreamMintManager.phaseGate, (collectionId, phaseId)), 192
            ),
            (IStreamMintManager.MintGateConfig)
        );
        bytes memory raw = _read(
            manager,
            abi.encodeCall(IStreamMintManager.phaseCounterIds, (collectionId, phaseId)),
            64 + 16 * 32
        );
        _arrayShape(raw, 16);
        result.counterIds = abi.decode(raw, (bytes32[]));
        IStreamMintManager.MintCounterConfig[] memory counters =
            new IStreamMintManager.MintCounterConfig[](result.counterIds.length);
        bool[] memory defined = new bool[](result.counterIds.length);
        IStreamMintCounterPolicy.Definition[] memory definitions =
            new IStreamMintCounterPolicy.Definition[](result.counterIds.length);
        for (uint256 i; i < result.counterIds.length; ++i) {
            bytes32 id = result.counterIds[i];
            counters[i] = abi.decode(
                _exact(
                    manager,
                    abi.encodeCall(IStreamMintManager.counterConfig, (collectionId, phaseId, id)),
                    224
                ),
                (IStreamMintManager.MintCounterConfig)
            );
            (defined[i], definitions[i]) = IStreamMintCounterPolicy(address(this))
                .counterDefinitionForManager(manager, counters[i].counterConfigHash);
            IStreamMintLedger.LedgerCounterPolicy memory registered = IStreamMintLedger(
                    address(this)
                ).registeredCounterPolicy(manager, collectionId, phaseId, id);
            IStreamMintManager.MintCounterConfig memory counter = counters[i];
            if (
                keccak256(abi.encode(registered))
                    != keccak256(
                        abi.encode(
                            counter.enabled,
                            counter.capMode,
                            counter.deltaMode,
                            counter.staticCap,
                            counter.staticIncrement,
                            counter.counterConfigHash
                        )
                    )
            ) {
                revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                    manager, collectionId, phaseId
                );
            }
        }
        result.configurationHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_MINT_PHASE_FREEZE_CONFIGURATION_V1"),
                block.chainid,
                core,
                registry,
                address(this),
                collectionId,
                phaseId,
                config,
                gate,
                result.counterIds,
                counters,
                defined,
                definitions,
                royaltyBranch,
                royalty.applicationConfigHash,
                royalty
            )
        );
        raw = _read(
            manager,
            abi.encodeCall(IStreamMintPhaseFreeze.phaseExecutors, (collectionId, phaseId)),
            64 + 64 * 32
        );
        _arrayShape(raw, 64);
        result.executors = abi.decode(raw, (address[]));
        for (uint256 i; i < result.executors.length; ++i) {
            if (result.executors[i] == address(0)) {
                revert IStreamMintLedgerImport.MintImportInvalid();
            }
            for (uint256 j; j < i; ++j) {
                if (result.executors[i] == result.executors[j]) {
                    revert IStreamMintLedgerImport.MintImportInvalid();
                }
            }
        }
    }

    /// @dev Only the verified Manager-domain wrapper is normalized. Original economic facts
    /// remain exact, and distinct branch tags prevent a raw config from impersonating a policy.
    function _royalty(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintManager.MintPhaseConfig memory config
    ) private view returns (bytes32 branch, IStreamMintRoyaltyPolicy.Policy memory p) {
        p = abi.decode(
            _exact(
                manager,
                abi.encodeCall(
                    IStreamMintRoyaltyPolicy.phaseRoyaltyPolicy, (collectionId, phaseId)
                ),
                224
            ),
            (IStreamMintRoyaltyPolicy.Policy)
        );
        if (!p.configured) {
            return (keccak256("6529STREAM_MINT_PHASE_FREEZE_ROYALTY_UNCONFIGURED_V1"), p);
        }
        bytes32 actual = keccak256(
            abi.encode(
                keccak256("6529STREAM_MINT_PHASE_ROYALTY_CONFIG_V1"),
                block.chainid,
                manager,
                collectionId,
                phaseId,
                p.applicationConfigHash,
                p.resolver,
                p.resolverRuntimeHash,
                uint8(2),
                p.electionHash,
                p.expectedModeAssignmentHash,
                p.expectedSourceRoyaltyPolicyHash
            )
        );
        if (config.configHash != actual) {
            revert IStreamMintLedgerPhaseFreeze.MintPhaseFreezePolicyMismatch(
                manager, collectionId, phaseId
            );
        }
        config.configHash = p.applicationConfigHash;
        branch = keccak256("6529STREAM_MINT_PHASE_FREEZE_ROYALTY_CONFIGURED_V1");
    }

    function _arrayShape(bytes memory raw, uint256 maximum) private pure {
        uint256 offset;
        uint256 count;
        assembly ("memory-safe") {
            offset := mload(add(raw, 32))
            count := mload(add(raw, 64))
        }
        if (raw.length < 64 || count > maximum || offset != 32 || raw.length != 64 + count * 32) {
            revert IStreamMintLedgerImport.MintImportInvalid();
        }
    }

    function _address(address target, bytes4 selector) private view returns (address) {
        return abi.decode(_exact(target, abi.encodeWithSelector(selector), 32), (address));
    }

    function _exact(address target, bytes memory input, uint256 size)
        private
        view
        returns (bytes memory result)
    {
        result = _read(target, input, size);
        if (result.length != size) revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(target);
    }

    /// @dev Copy bound comes from the original static ABI or the16-counter/64-executor limits.
    function _read(address target, bytes memory input, uint256 maximum)
        private
        view
        returns (bytes memory result)
    {
        result = new bytes(maximum);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(input, 32), mload(input), add(result, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) revert IStreamMintPhaseFreeze.MintPhaseFreezeReadFailed(target);
        assembly ("memory-safe") { mstore(result, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintManager.sol";
import "./StreamMintArtistConsent.sol";
import "./StreamMintGateValidator.sol";
import "./StreamMintOperationIdentity.sol";
import "./StreamMintCounterPolicy.sol";
import "./StreamMintPhaseFreezeControl.sol";

/// @notice Linked configuration and bookkeeping for Manager-owned phase state.
/// @dev Delegatecalls retain Manager storage, msg.sender and event emitter. Public
///      owner/reentrancy checks stay in Manager; configuration invokes full artist
///      consent before Ledger registration and every failure rolls back all writes.
library StreamMintPhaseState {
    struct PhaseState {
        bool exists;
        IStreamMintManager.MintPhaseConfig config;
    }

    struct ConfigurationContext {
        StreamMintOperationIdentity.PolicyContext policy;
        address core;
        uint256 artistGasLimit;
        uint32 maxBatchQuantity;
        uint16 maxCounters;
    }

    struct ConfigurationArguments {
        uint256 collectionId;
        bytes32 phaseId;
        IStreamMintManager.MintPhaseConfig config;
        IStreamMintManager.MintGateConfig gateConfig;
        bytes32[] counterIds;
        IStreamMintManager.MintCounterConfig[] counterConfigs;
    }

    uint16 private constant SCHEMA_VERSION = 1;

    /// @notice Adds/removes one executor, returning false for an unchanged authorization.
    /// @dev Manager owns admission and performs consent-gated policy registration after this write.
    function setExecutor(
        mapping(address => bool) storage authorized,
        address[] storage executors,
        mapping(address => uint256) storage indexPlusOne,
        address executor,
        bool allowed,
        uint16 maxExecutors
    ) external returns (bool changed) {
        if (executor == address(0)) {
            revert IStreamMintManager.InvalidMintExecutor(executor);
        }
        if (authorized[executor] == allowed) return false;
        authorized[executor] = allowed;
        if (allowed) {
            uint256 count = executors.length;
            if (count >= maxExecutors) {
                revert IStreamMintManager.MintExecutorCountLimitExceeded(count + 1, maxExecutors);
            }
            indexPlusOne[executor] = count + 1;
            executors.push(executor);
        } else {
            uint256 position = indexPlusOne[executor];
            if (position != 0) {
                uint256 index = position - 1;
                address last = executors[executors.length - 1];
                if (index != executors.length - 1) {
                    executors[index] = last;
                    indexPlusOne[last] = position;
                }
                executors.pop();
                delete indexPlusOne[executor];
            }
        }
        return true;
    }

    event MintPhaseConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed policyHash,
        uint64 startTime,
        uint64 endTime,
        uint32 maxBatchQuantity,
        bytes32 configHash,
        bytes32 metadataHash,
        address admin
    );

    event MintCounterConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed counterId,
        IStreamMintManager.CounterKeyMode keyMode,
        IStreamMintLedger.CounterCapMode capMode,
        IStreamMintLedger.CounterDeltaMode deltaMode,
        uint64 staticCap,
        uint64 staticIncrement,
        bytes32 counterConfigHash,
        bytes32 policyHash
    );

    event MintPhaseGateConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed gate,
        bytes32 gateConfigHash,
        bytes32 gateCodehash,
        bytes32 gateMetadataHash,
        uint32 gateSemanticVersion,
        uint32 gateGasLimit,
        bytes32 policyHash
    );

    event MintPhaseConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed policyHash,
        uint8 consentMode,
        bytes32 consentEvidenceHash
    );

    /// @notice Validates, stores and registers one newly admitted phase atomically.
    /// @dev Only Manager supplies storage/context after checking owner, reentrancy and phase identity.
    function configure(
        PhaseState storage phaseState,
        mapping(bytes32 => IStreamMintManager.MintGateConfig) storage storedGates,
        bytes32[] storage storedIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage storedCounters,
        address[] storage executors,
        mapping(address => bool) storage authorized,
        mapping(address => uint256) storage indexPlusOne,
        mapping(bytes32 => bytes32) storage policyHashes,
        bytes calldata arguments,
        ConfigurationContext memory context
    ) external returns (bytes32 policyHash) {
        uint256 collectionId = context.policy.collectionId;
        bytes32 phaseId = context.policy.phaseId;
        // The original configurePhase ABI is decoded by a fixed linked worker. Storage
        // references and dependencies still originate exclusively at the guarded host.
        (,, IStreamMintManager.MintPhaseConfig memory config) =
            abi.decode(arguments, (uint256, bytes32, IStreamMintManager.MintPhaseConfig));
        _requirePhaseConfig(collectionId, phaseId, config, context.maxBatchQuantity);
        _requireArgumentBounds(arguments, context.maxCounters);
        ConfigurationArguments memory args =
            abi.decode(bytes.concat(bytes32(uint256(32)), arguments), (ConfigurationArguments));
        if (args.collectionId != collectionId || args.phaseId != phaseId) {
            revert IStreamMintManager.InvalidMintPhase(collectionId, phaseId);
        }
        IStreamMintManager.MintGateConfig memory gateConfig = args.gateConfig;
        bytes32[] memory counterIds = args.counterIds;
        IStreamMintManager.MintCounterConfig[] memory counterConfigs = args.counterConfigs;

        bytes32[] memory ids = _copyCounterIds(counterIds);
        IStreamMintLedger.LedgerCounterPolicy[] memory ledgerPolicies =
            new IStreamMintLedger.LedgerCounterPolicy[](counterIds.length);
        for (uint256 i = 0; i < counterIds.length; i++) {
            _requireNoDuplicateCounterId(counterIds, i);
            _requireStaticCounterConfig(counterIds[i], counterConfigs[i]);
            StreamMintCounterPolicy.validateConfig(
                context.policy.ledger, counterIds[i], counterConfigs[i]
            );
            ledgerPolicies[i] = _ledgerPolicy(counterConfigs[i]);
        }
        IStreamMintManager.MintGateConfig memory validatedGateConfig =
            StreamMintGateValidator.validateConfiguration(
                gateConfig, IERC165(context.policy.moduleRegistry)
            );

        _replacePhaseCounters(storedIds, storedCounters, ids, counterConfigs);
        storedGates[phaseId] = validatedGateConfig;
        phaseState.exists = true;
        phaseState.config = config;

        StreamMintPhaseFreezeControl.inheritExecutors(
            authorized, executors, indexPlusOne, context.policy.ledger, collectionId, phaseId
        );
        policyHash = StreamMintOperationIdentity.computePolicyHash(
            config, validatedGateConfig, ids, counterConfigs, executors, context.policy
        );
        (uint8 mode, bytes32 evidence) = StreamMintArtistConsent.registration(
            context.core, collectionId, phaseId, policyHash, context.artistGasLimit
        );
        emit MintPhaseConsentRecorded(
            SCHEMA_VERSION, collectionId, phaseId, policyHash, mode, evidence
        );
        policyHashes[phaseId] = policyHash;
        IStreamMintLedger(context.policy.ledger)
            .registerPhasePolicy(
                address(this), collectionId, phaseId, policyHash, ids, ledgerPolicies, 0
            );

        _emitPhaseConfigured(collectionId, phaseId, config, policyHash);
        for (uint256 i = 0; i < counterIds.length; i++) {
            _emitCounterConfigured(
                collectionId, phaseId, counterIds[i], counterConfigs[i], policyHash
            );
        }
        _emitGateConfigured(collectionId, phaseId, validatedGateConfig, policyHash);
    }

    /// @dev Inspect original ABI array heads before allocating either dynamic array.
    function _requireArgumentBounds(bytes calldata arguments, uint16 maximum) private pure {
        // collection/phase + six phase words + six gate words + two array offsets.
        if (arguments.length < 512) revert IStreamMintManager.MintArrayLengthMismatch();
        uint256 idsOffset;
        uint256 configsOffset;
        assembly ("memory-safe") {
            idsOffset := calldataload(add(arguments.offset, 448))
            configsOffset := calldataload(add(arguments.offset, 480))
        }
        if (idsOffset > arguments.length - 32 || configsOffset > arguments.length - 32) {
            revert IStreamMintManager.MintArrayLengthMismatch();
        }
        uint256 count;
        uint256 configCount;
        assembly ("memory-safe") {
            count := calldataload(add(arguments.offset, idsOffset))
            configCount := calldataload(add(arguments.offset, configsOffset))
        }
        if (count == 0 || count != configCount) {
            revert IStreamMintManager.MintArrayLengthMismatch();
        }
        if (count > maximum) {
            revert IStreamMintManager.MintCounterCountLimitExceeded(count, maximum);
        }
    }

    function _copyCounterIds(bytes32[] memory counterIds)
        private
        pure
        returns (bytes32[] memory ids)
    {
        ids = new bytes32[](counterIds.length);
        for (uint256 i = 0; i < counterIds.length; i++) {
            ids[i] = counterIds[i];
        }
    }

    function _ledgerPolicy(IStreamMintManager.MintCounterConfig memory config)
        private
        pure
        returns (IStreamMintLedger.LedgerCounterPolicy memory)
    {
        return IStreamMintLedger.LedgerCounterPolicy({
            enabled: config.enabled,
            capMode: config.capMode,
            deltaMode: config.deltaMode,
            staticCap: config.staticCap,
            staticIncrement: config.staticIncrement,
            counterConfigHash: config.counterConfigHash
        });
    }

    function _requirePhaseConfig(
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintManager.MintPhaseConfig memory config,
        uint32 maximum
    ) private pure {
        if (config.endTime != 0 && config.startTime != 0 && config.endTime < config.startTime) {
            revert IStreamMintManager.InvalidMintPhase(collectionId, phaseId);
        }
        if (config.maxBatchQuantity == 0 || config.maxBatchQuantity > maximum) {
            revert IStreamMintManager.InvalidMintBatchLimit(config.maxBatchQuantity, maximum);
        }
    }

    function _requireNoDuplicateCounterId(bytes32[] memory counterIds, uint256 index) private pure {
        bytes32 counterId = counterIds[index];
        if (counterId == bytes32(0)) {
            revert IStreamMintManager.InvalidMintCounter(counterId);
        }
        for (uint256 i = 0; i < index; i++) {
            if (counterIds[i] == counterId) {
                revert IStreamMintManager.DuplicateMintCounter(counterId);
            }
        }
    }

    function _requireStaticCounterConfig(
        bytes32 counterId,
        IStreamMintManager.MintCounterConfig memory config
    ) private pure {
        if (
            !config.enabled || config.keyMode == IStreamMintManager.CounterKeyMode.UNKNOWN
                || config.staticIncrement == 0 || config.counterConfigHash == bytes32(0)
        ) {
            revert IStreamMintManager.InvalidMintCounter(counterId);
        }
        if (
            config.deltaMode != IStreamMintLedger.CounterDeltaMode.STATIC
                || config.capMode == IStreamMintLedger.CounterCapMode.RESOLVER
        ) {
            revert IStreamMintManager.UnsupportedMintCounterMode(counterId);
        }
        if (config.capMode == IStreamMintLedger.CounterCapMode.STATIC && config.staticCap == 0) {
            revert IStreamMintManager.InvalidMintCounter(counterId);
        }
        if (config.capMode == IStreamMintLedger.CounterCapMode.NONE && config.staticCap != 0) {
            revert IStreamMintManager.InvalidMintCounter(counterId);
        }
    }

    function _emitCounterConfigured(
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        IStreamMintManager.MintCounterConfig memory config,
        bytes32 policyHash
    ) private {
        emit MintCounterConfigured(
            collectionId,
            phaseId,
            counterId,
            config.keyMode,
            config.capMode,
            config.deltaMode,
            config.staticCap,
            config.staticIncrement,
            config.counterConfigHash,
            policyHash
        );
    }

    function _emitPhaseConfigured(
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintManager.MintPhaseConfig memory config,
        bytes32 policyHash
    ) private {
        emit MintPhaseConfigured(
            collectionId,
            phaseId,
            policyHash,
            config.startTime,
            config.endTime,
            config.maxBatchQuantity,
            config.configHash,
            config.metadataHash,
            msg.sender
        );
    }

    function _emitGateConfigured(
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintManager.MintGateConfig memory gateConfig,
        bytes32 policyHash
    ) private {
        emit MintPhaseGateConfigured(
            collectionId,
            phaseId,
            gateConfig.gate,
            gateConfig.gateConfigHash,
            gateConfig.gateCodehash,
            gateConfig.gateMetadataHash,
            gateConfig.gateSemanticVersion,
            gateConfig.gateGasLimit,
            policyHash
        );
    }

    function _replacePhaseCounters(
        bytes32[] storage existing,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage stored,
        bytes32[] memory ids,
        IStreamMintManager.MintCounterConfig[] memory configs
    ) private {
        for (uint256 i; i < existing.length; ++i) {
            delete stored[existing[i]];
        }
        while (existing.length != 0) existing.pop();
        for (uint256 i; i < ids.length; ++i) {
            existing.push(ids[i]);
            stored[ids[i]] = configs[i];
        }
    }

    /// @notice Hashes the exact active stored phase, counters, gate and canonical executor set.
    function computeStoredPolicyHash(
        PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage storedIds,
        mapping(
            bytes32 => IStreamMintManager.MintCounterConfig
        ) storage stored,
        address[] storage executors,
        StreamMintOperationIdentity.PolicyContext memory context
    ) external view returns (bytes32) {
        bytes32[] memory ids = storedIds;
        IStreamMintManager.MintCounterConfig[] memory configs =
            new IStreamMintManager.MintCounterConfig[](ids.length);
        for (uint256 i; i < ids.length; ++i) {
            configs[i] = stored[ids[i]];
        }
        return StreamMintOperationIdentity.computePolicyHash(
            phaseState.config, gate, ids, configs, executors, context
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintPreview.sol";
import "../../interfaces/stream/mint/IStreamMintReads.sol";
import "../../interfaces/stream/mint/IStreamMintPhaseFreeze.sol";
import "../../interfaces/stream/mint/IStreamMintLedgerContinuity.sol";
import "../../interfaces/stream/mint/IStreamMintLedgerImport.sol";
import "./StreamMintManagerTranscript.sol";
import "./StreamMintRoyaltyPolicy.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Fixed linked implementation of the Manager's advisory read capability.
/// @dev The bounded self-STATICCALL catches failure without changing the gate's actual caller.
/// The self-call branch evaluates once; it never dispatches another self-call. All executor
/// semantics use the explicit argument. No result is an execution authorization or identity.
library StreamMintPreview {
    uint256 private constant MAX_ROWS = 160; // Original 16 counters times 10 tokens.
    uint256 private constant MAX_RESULT_BYTES = 256 + MAX_ROWS * 288;
    uint256 private constant RETURN_GAS_RESERVE = 100_000;
    bytes32 private constant ARTIST_GAS = keccak256("6529STREAM_GGP_ARTIST_AUTHORITY_GAS_LIMIT");

    struct Phase {
        IStreamMintManager.MintPhaseConfig config;
        IStreamMintManager.MintGateConfig gate;
        bytes32[] ids;
        IStreamMintManager.MintCounterConfig[] counters;
    }

    function read(
        IStreamMintManager.MintBatch calldata batch,
        address executor,
        bytes calldata gateData
    ) external view returns (bytes memory encoded) {
        if (msg.sender == address(this)) {
            return abi.encode(_evaluate(batch, executor, gateData));
        }

        IStreamMintPreview.MintPreview memory failure;
        failure.quantity = batch.initialRecipients.length;
        failure.reason = IStreamMintPreview.MintPreviewUnavailable.selector;
        failure.counters = new IStreamMintPreview.CounterPreview[](0);
        // A typed library DELEGATECALL has the library selector, not the facade selector.
        bytes memory payload =
            abi.encodeCall(IStreamMintPreview.canMint, (batch, executor, gateData));
        uint256 available = gasleft();
        if (available <= RETURN_GAS_RESERVE + 10_000) return abi.encode(failure);
        uint256 forwarded = available - RETURN_GAS_RESERVE;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, address(), add(payload, 32), mload(payload), 0, 0)
            size := returndatasize()
        }
        if (!ok) {
            // Never allocate or copy a dependency's arbitrary revert payload.
            if (size >= 4 && size <= MAX_RESULT_BYTES) {
                bytes4 reason;
                assembly ("memory-safe") {
                    returndatacopy(0, 0, 4)
                    reason := mload(0)
                }
                if (reason != bytes4(0)) failure.reason = reason;
            }
            return abi.encode(failure);
        }
        if (size < 256 || size > MAX_RESULT_BYTES) return abi.encode(failure);
        encoded = new bytes(size);
        assembly ("memory-safe") {
            returndatacopy(add(encoded, 32), 0, size)
        }
        uint256 outerOffset;
        uint256 allowed;
        uint256 rowsOffset;
        uint256 count;
        assembly ("memory-safe") {
            outerOffset := mload(add(encoded, 32))
            allowed := mload(add(encoded, 64))
            rowsOffset := mload(add(encoded, 224))
            count := mload(add(encoded, 256))
        }
        if (
            outerOffset != 32 || allowed > 1 || rowsOffset != 192 || count > MAX_ROWS
                || size != 256 + count * 288
        ) return abi.encode(failure);
    }

    function _evaluate(
        IStreamMintManager.MintBatch calldata batch,
        address executor,
        bytes calldata gateData
    ) private view returns (IStreamMintPreview.MintPreview memory result) {
        IStreamMintReads host = IStreamMintReads(address(this));
        IStreamMintLedger ledger = host.mintLedger();
        address core = address(host.core());
        IERC165 registry = host.moduleRegistry();
        Phase memory p = _phase(host, batch, executor);
        StreamMintRoyaltyPolicy.requireCurrent(
            IStreamMintRoyaltyPolicy(address(this))
                .phaseRoyaltyPolicy(batch.collectionId, batch.phaseId),
            StreamMintRoyaltyPolicy.Context(core, address(registry)),
            batch.collectionId,
            batch.phaseId,
            p.config.configHash,
            false
        );
        result.quantity = StreamMintManagerTranscript.validateMintBatch(batch, p.config);
        result.policyHash = StreamMintOperationIdentity.computePolicyHash(
            p.config,
            p.gate,
            p.ids,
            p.counters,
            IStreamMintPhaseFreeze(address(this)).phaseExecutors(batch.collectionId, batch.phaseId),
            StreamMintOperationIdentity.PolicyContext(
                block.chainid,
                address(this),
                address(ledger),
                address(registry),
                1,
                batch.collectionId,
                batch.phaseId
            )
        );
        bytes32 registered = host.phasePolicyHash(batch.collectionId, batch.phaseId);
        if (registered != result.policyHash) {
            revert IStreamMintManager.MintPolicyHashMismatch(registered, result.policyHash);
        }
        bytes32 bound =
            StreamMintManagerTranscript.requireBoundPolicyHash(batch, result.policyHash, ledger);
        StreamMintArtistConsent.mint(
            core,
            batch.collectionId,
            batch.phaseId,
            result.policyHash,
            IStreamGasParameterHost(address(this)).gasParameter(ARTIST_GAS)
        );
        StreamMintOperationIdentity.MintAuthorization memory authorization =
            StreamMintGateValidator.validateAuthorization(
                batch, gateData, result.quantity, bound, p.gate, registry, executor
            );
        result.gateHash = authorization.gateHash;
        IStreamMintLedger.CounterConsumption[] memory rows = StreamMintCounterPreparation.preview(
            batch,
            result.quantity,
            p.ids,
            p.counters,
            StreamMintOperationIdentity.CounterContext(
                block.chainid, address(this), address(ledger), executor, authorization.authorizer
            )
        );
        (result.counters, result.allowed) = _counters(ledger, rows);
        if (!result.allowed) {
            result.reason = IStreamMintLedger.CounterCapExceeded.selector;
            return result;
        }
        uint256 nonce = host.nextOperationNonce();
        if (type(uint256).max - nonce < result.quantity) {
            revert IStreamMintManager.MintOperationNonceOverflow(nonce, result.quantity);
        }
        _ledgerState(ledger, batch, p, result.policyHash, authorization);
    }

    function _phase(
        IStreamMintReads host,
        IStreamMintManager.MintBatch calldata batch,
        address executor
    ) private view returns (Phase memory p) {
        if (batch.collectionId == 0 || batch.phaseId == bytes32(0)) {
            revert IStreamMintManager.InvalidMintPhase(batch.collectionId, batch.phaseId);
        }
        bool exists;
        (exists, p.config) = host.phase(batch.collectionId, batch.phaseId);
        if (!exists) {
            revert IStreamMintManager.MintPhaseDoesNotExist(batch.collectionId, batch.phaseId);
        }
        if (p.config.paused) {
            revert IStreamMintManager.MintPhasePaused(batch.collectionId, batch.phaseId);
        }
        if (p.config.startTime != 0 && block.timestamp < p.config.startTime) {
            revert IStreamMintManager.MintPhaseNotStarted(
                batch.collectionId, batch.phaseId, block.timestamp
            );
        }
        if (p.config.endTime != 0 && block.timestamp > p.config.endTime) {
            revert IStreamMintManager.MintPhaseEnded(
                batch.collectionId, batch.phaseId, block.timestamp
            );
        }
        if (!host.phaseExecutor(batch.collectionId, batch.phaseId, executor)) {
            revert IStreamMintManager.UnauthorizedMintExecutor(
                batch.collectionId, batch.phaseId, executor
            );
        }
        p.gate = host.phaseGate(batch.collectionId, batch.phaseId);
        p.ids = host.phaseCounterIds(batch.collectionId, batch.phaseId);
        if (p.ids.length > 16) revert IStreamMintPreview.MintPreviewUnavailable();
        p.counters = new IStreamMintManager.MintCounterConfig[](p.ids.length);
        for (uint256 i; i < p.ids.length; ++i) {
            p.counters[i] = host.counterConfig(batch.collectionId, batch.phaseId, p.ids[i]);
        }
    }

    function _counters(IStreamMintLedger ledger, IStreamMintLedger.CounterConsumption[] memory rows)
        private
        view
        returns (IStreamMintPreview.CounterPreview[] memory previews, bool allowed)
    {
        if (rows.length > MAX_ROWS) revert IStreamMintPreview.MintPreviewUnavailable();
        previews = new IStreamMintPreview.CounterPreview[](rows.length);
        allowed = true;
        for (uint256 i; i < rows.length; ++i) {
            uint64 current = ledger.counterValue(rows[i].valueKey);
            uint256 projected = current;
            for (uint256 j; j < rows.length; ++j) {
                if (rows[i].valueKey == rows[j].valueKey) projected += rows[j].increment;
            }
            if (projected > type(uint64).max) {
                revert IStreamMintLedger.CounterValueOverflow(rows[i].valueKey);
            }
            bool rowAllowed = rows[i].cap == 0 || projected <= rows[i].cap;
            if (!rowAllowed) allowed = false;
            previews[i] = IStreamMintPreview.CounterPreview(
                rows[i].counterId,
                rows[i].subjectKey,
                rows[i].valueKey,
                current,
                rows[i].increment,
                uint64(projected),
                rows[i].cap,
                rowAllowed,
                rows[i].resolutionHash
            );
        }
    }

    function _ledgerState(
        IStreamMintLedger ledger,
        IStreamMintManager.MintBatch calldata batch,
        Phase memory p,
        bytes32 currentPolicy,
        StreamMintOperationIdentity.MintAuthorization memory authorization
    ) private view {
        if (!ledger.ledgerWriter(address(this))) {
            revert IStreamMintLedger.UnauthorizedLedgerWriter(address(this));
        }
        IStreamMintLedgerContinuity continuity = IStreamMintLedgerContinuity(address(ledger));
        if (continuity.mintAncestorCount(address(this)) != 0) {
            (address ancestorLedger, address ancestor) = continuity.mintAncestorAt(address(this), 0);
            if (!continuity.isCompletedMintDescendant(ancestorLedger, ancestor, address(this))) {
                revert IStreamMintLedgerImport.MintImportNotReady(address(this));
            }
        }
        if (
            ledger.registeredPhasePolicyHash(address(this), batch.collectionId, batch.phaseId)
                != currentPolicy
        ) {
            revert IStreamMintLedger.InvalidPhasePolicy(
                address(this), batch.collectionId, batch.phaseId
            );
        }
        if (ledger.isManagerAuthorizationUsed(address(this), authorization.authorizationId)) {
            revert IStreamMintLedger.AuthorizationAlreadyConsumed(authorization.authorizationId);
        }
        for (uint256 i; i < authorization.nullifiers.length; ++i) {
            if (ledger.isManagerNullifierUsed(address(this), authorization.nullifiers[i])) {
                revert IStreamMintLedger.NullifierAlreadyConsumed(authorization.nullifiers[i]);
            }
        }
        for (uint256 i; i < p.ids.length; ++i) {
            IStreamMintLedger.LedgerCounterPolicy memory registered = ledger.registeredCounterPolicy(
                address(this), batch.collectionId, batch.phaseId, p.ids[i]
            );
            IStreamMintManager.MintCounterConfig memory c = p.counters[i];
            if (!registered.enabled) {
                revert IStreamMintLedger.CounterPolicyNotRegistered(
                    address(this), batch.collectionId, batch.phaseId, p.ids[i]
                );
            }
            if (
                registered.enabled != c.enabled || registered.capMode != c.capMode
                    || registered.deltaMode != c.deltaMode || registered.staticCap != c.staticCap
                    || registered.staticIncrement != c.staticIncrement
                    || registered.counterConfigHash != c.counterConfigHash
            ) revert IStreamMintLedger.CounterPolicyMismatch(p.ids[i]);
        }
    }
}

