pragma solidity ^0.8.19;

import { StreamMintRoyaltyPolicy } from "./StreamMintRoyaltyPolicy.sol";

import "../../interfaces/stream/mint/IStreamPreparedNativeMint.sol";
import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";
import "./StreamPreparedNativeMintExecution.sol";
import "./StreamPreparedNativeContentExecution.sol";
import "../revenue/StreamPreparedNativeContentPurchaseValidation.sol";

/// @notice Typed paid preparation in Manager's storage/caller context, never an arbitrary hook.
library StreamPreparedNativeContentPurchaseExecution {
    function admit(
        StreamPreparedNativeContentExecution.State storage contentState,
        address registry,
        IStreamMintManager.MintBatch calldata batch,
        bytes calldata gateData,
        bytes32 hash
    ) public {
        if (contentState.admissionHash != 0 || contentState.active.operationRoot != 0) revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        address recorder = StreamPreparedNativeContentPurchaseValidation.addressWord(
            msg.sender, "primarySaleSettlement()"
        );
        StreamPreparedNativeSettlementTypes.Intent memory i =
            StreamPreparedNativeContentPurchaseValidation.readIntent(msg.sender, recorder, hash);
        StreamPreparedNativeContentTypes.Facts memory c =
            StreamPreparedNativeContentPurchaseReads.requireBatch(
                registry, batch, gateData, hash, i
            );
        if (i.contentSelectionHash != c.contentLeaf) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        contentState.admissionHash = StreamPreparedNativeContentPurchaseHash.admissionHash(
            msg.sender,
            hash,
            StreamPreparedNativeContentPurchaseHash.readPurchase(msg.sender, hash, i),
            c
        );
        _storeContent(contentState.active, c);
    }

    event PreparedMintStarted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        uint256 collectionSerial,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    event PreparedMintCompleted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        address initialRecipient
    );

    function execute(
        StreamPreparedNativeMintExecution.State storage state,
        StreamPreparedNativeContentExecution.State storage contentState,
        bytes calldata gateData,
        IStreamMintManager.MintBatch calldata batch,
        StreamPreparedNativeMintExecution.Operation memory op
    )
        public
        returns (
            uint256 tokenId,
            StreamPrimarySettlementTypes.PrimarySettlementResult memory result
        )
    {
        if (
            state.recorder == address(0) || state.active.operationRoot != 0
                || batch.initialRecipients.length != 1 || batch.initialRecipients[0] != msg.sender
                || batch.tokenData[0].length > 8192 || op.intentHash == 0
        ) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        StreamPreparedNativeSettlementAdmission.requireModule(op.registry, msg.sender);
        StreamPreparedNativeSettlementTypes.Facts memory f;
        f.saleAdapter = msg.sender;
        f.mintManager = address(this);
        f.recorder = StreamPreparedNativeContentPurchaseValidation.addressWord(
            msg.sender, "primarySaleSettlement()"
        );
        f.recorderCodeHash =
            StreamPreparedNativeContentPurchaseValidation.word(msg.sender, "settlementCodeHash()");
        f.collectionId = batch.collectionId;
        f.phaseId = batch.phaseId;
        f.intentHash = op.intentHash;
        f.operationRoot = op.operationRoot;
        f.operationId = op.operationId;
        f.payer = batch.payer;
        f.initialRecipient = batch.initialRecipients[0];
        f.beneficiary = batch.beneficiaries[0];
        f.tokenDataHash = keccak256(batch.tokenData[0]);
        f.mintCommitment = batch.mintCommitments[0];
        f.currentPolicyHash = op.currentPolicyHash;
        f.boundPolicyHash = op.boundPolicyHash;
        StreamPreparedNativeSettlementTypes.Intent memory intent =
            StreamPreparedNativeContentPurchaseValidation.readIntent(
                msg.sender, f.recorder, f.intentHash
            );
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, intent.saleId
        );
        StreamPreparedNativeContentPurchaseValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        StreamPreparedNativeContentPurchaseValidation.requireIntentFields(f, intent);
        StreamPreparedNativeContentTypes.Facts memory content =
            StreamPreparedNativeContentPurchaseReads.requireBatch(
                op.registry, batch, gateData, op.intentHash, intent
            );
        if (content.contentLeaf != intent.contentSelectionHash) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        if (
            contentState.admissionHash
                    != StreamPreparedNativeContentPurchaseHash.admissionHash(
                        msg.sender,
                        op.intentHash,
                        StreamPreparedNativeContentPurchaseHash.readPurchase(
                            msg.sender, op.intentHash, intent
                        ),
                        content
                    )
                || keccak256(abi.encode(contentState.active)) != keccak256(abi.encode(content))
        ) revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        content.operationRoot = f.operationRoot;
        (f.tokenId, f.collectionSerial) = op.core
            .prepareMintFromManager(
                batch.collectionId, batch.tokenData[0], f.tokenDataHash, f.operationId
            );
        state.active = f;
        if (
            contentState.admissionHash
                != StreamPreparedNativeContentPurchaseHash.admissionHash(
                    msg.sender,
                    op.intentHash,
                    StreamPreparedNativeContentPurchaseHash.readPurchase(
                        msg.sender, op.intentHash, intent
                    ),
                    contentState.active
                )
        ) revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        _storeContent(contentState.active, content);
        StreamMintRoyaltyPolicy.snapshot(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintStarted(
            1,
            f.operationId,
            f.tokenId,
            f.collectionId,
            f.operationRoot,
            f.collectionSerial,
            f.beneficiary,
            f.tokenDataHash,
            f.mintCommitment
        );
        result = _callback(f, op.callbackGas);
        _requireResult(f, intent, result);
        StreamPreparedNativeContentPurchaseValidation.requireActive(
            address(op.core), op.registry, f, intent
        );
        op.core
            .completePreparedMintFromManager(
                f.tokenId, f.initialRecipient, f.operationId, f.mintCommitment
            );
        _requireResult(f, intent, result);
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, intent.saleId
        );
        StreamPreparedNativeContentPurchaseValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        if (
            op.core.ownerOf(f.tokenId) != f.initialRecipient
                || op.core.pendingPreparedMintTokenId() != 0
                || op.core.tokenLifecycle(f.tokenId) != 2
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        StreamPreparedNativeContentPurchaseReads.requireActive(op.registry, f, intent);
        StreamMintRoyaltyPolicy.completed(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintCompleted(
            1, f.operationId, f.tokenId, f.collectionId, f.operationRoot, f.initialRecipient
        );
        tokenId = f.tokenId;
        delete state.active;
        StreamPreparedNativeContentTypes.Facts memory empty;
        _storeContent(contentState.active, empty);
        delete contentState.admissionHash;
    }

    function _callback(StreamPreparedNativeSettlementTypes.Facts memory facts, uint256 cap)
        private
        returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result)
    {
        bytes memory data = abi.encodeCall(
            IStreamPreparedNativeContentSale.onPreparedNativeContentMint, (facts)
        );
        bytes memory raw = new bytes(416);
        uint256 available = gasleft();
        if (cap == 0 || cap > type(uint64).max) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        uint256 required = cap + cap / 63 + 1_000_000;
        if (available <= required) {
            revert IStreamPreparedNativeMint.InsufficientPreparedNativeGas(available, required);
        }
        address sale = facts.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(cap, sale, 0, add(data, 32), mload(data), add(raw, 32), 416)
            size := returndatasize()
        }
        if (!ok || size != 416) {
            revert IStreamPreparedNativeMint.PreparedNativeCallFailed(
                sale, IStreamPreparedNativeContentSale.onPreparedNativeContentMint.selector
            );
        }
        bytes4 magic;
        (magic, result) =
            abi.decode(raw, (bytes4, StreamPrimarySettlementTypes.PrimarySettlementResult));
        if (
            magic != IStreamPreparedNativeContentSale.onPreparedNativeContentMint.selector
                || keccak256(raw) != keccak256(abi.encode(magic, result))
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }

    function _requireResult(
        StreamPreparedNativeSettlementTypes.Facts memory f,
        StreamPreparedNativeSettlementTypes.Intent memory intent,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory result
    ) private view {
        if (f.recorder.codehash != f.recorderCodeHash) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        bytes memory raw = StreamPreparedNativeContentPurchaseValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementResult, (result.settlementKey)),
            384
        );
        if (
            keccak256(raw) != keccak256(abi.encode(result)) || result.candidateCommitment == 0
                || result.settlementKey == 0 || result.profileId == 0 || result.wallet == address(0)
                || result.asset != address(0) || result.amount != intent.amount
                || result.executor != intent.executor
                || result.executionId != StreamPreparedNativeSettlementHash.executionId(f, intent)
                || result.operationIdentityCommitment != f.operationRoot
                || result.currentPolicyHash != f.currentPolicyHash
                || result.boundPolicyHash != f.boundPolicyHash
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        raw = StreamPreparedNativeContentPurchaseValidation.read(
            f.recorder,
            abi.encodeCall(
                IStreamPreparedNativePrimarySaleSettlement.preparedNativeFactsHash,
                (result.settlementKey)
            ),
            32
        );
        if (abi.decode(raw, (bytes32)) != StreamPreparedNativeSettlementHash.factsHash(f)) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        StreamPreparedNativeContentTypes.Facts memory content =
            IStreamPreparedNativeContentMint(address(this)).activePreparedNativeContent();
        if (
            IStreamPreparedNativeContentSettlement(f.recorder)
                    .preparedNativeContentHash(result.settlementKey)
                != StreamPreparedNativeContentHash.factsHash(content)
        ) revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        raw = StreamPreparedNativeContentPurchaseValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementConsumed, (result.settlementKey)),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }

    function _storeContent(
        StreamPreparedNativeContentTypes.Facts storage a,
        StreamPreparedNativeContentTypes.Facts memory b
    ) private {
        a.operationRoot = b.operationRoot;
        a.gate = b.gate;
        a.gateCodeHash = b.gateCodeHash;
        a.gateConfigHash = b.gateConfigHash;
        a.manifestRoot = b.manifestRoot;
        a.manifestHash = b.manifestHash;
        a.counterId = b.counterId;
        a.contentId = b.contentId;
        a.tokenDataHash = b.tokenDataHash;
        a.contentLeaf = b.contentLeaf;
        a.contextHash = b.contextHash;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/mint/IStreamPreparedNativeContentPurchaseMint.sol";
import "./StreamPrivateSaleHash.sol";
import "./StreamMintTicketHash.sol";

/// @notice The original purchase and signed authorization domains, with a separate admission profile.
library StreamPreparedNativeContentPurchaseHash {
    error InvalidPreparedNativeContentPurchase();

    function purchaseId(address house, bytes32 saleId, address buyer, uint256 nonce)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_SALE_PURCHASE_V1"), block.chainid, house, saleId, buyer, nonce
            )
        );
    }

    function admissionHash(
        address house,
        bytes32 intentHash,
        StreamPreparedNativeContentPurchaseTypes.Purchase memory p,
        StreamPreparedNativeContentTypes.Facts memory c
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PREPARED_NATIVE_CONTENT_PURCHASE_ADMISSION_V1"),
                block.chainid,
                house,
                intentHash,
                p,
                c
            )
        );
    }

    function readPurchase(
        address house,
        bytes32 intentHash,
        StreamPreparedNativeSettlementTypes.Intent memory i
    ) public view returns (StreamPreparedNativeContentPurchaseTypes.Purchase memory p) {
        bytes memory input = abi.encodeCall(
            IStreamPreparedNativeContentPurchaseSale.activePreparedNativeContentPurchase,
            (intentHash)
        );
        bytes memory raw = new bytes(320);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), house, add(input, 32), mload(input), add(raw, 32), 320)
            size := returndatasize()
        }
        if (!ok || size != 320) revert InvalidPreparedNativeContentPurchase();
        p = abi.decode(raw, (StreamPreparedNativeContentPurchaseTypes.Purchase));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || intentHash == 0 || p.saleId == 0
                || p.saleId != i.saleId || p.saleNonce == 0 || p.saleNonce != i.saleNonce
                || p.saleConfigHash == 0 || p.buyer == address(0) || p.buyer != i.payer
                || p.purchaseNonce == 0 || p.purchaseNonce != i.executionNonce
                || p.purchaseId != purchaseId(house, p.saleId, p.buyer, p.purchaseNonce)
                || p.authorizationId == 0 || p.primaryPolicyMode > 1
                || p.primaryPolicyMode != i.primaryPolicyMode
        ) revert InvalidPreparedNativeContentPurchase();
        if (i.authorityMode == 2) {
            if (
                p.authorizationId != intentHash || p.authorizer != address(0)
                    || p.authorizerKind != 0
            ) {
                revert InvalidPreparedNativeContentPurchase();
            }
        } else if (i.authorityMode == 1) {
            if (
                p.authorizationId != StreamMintTicketHash.authorizationId(i.saleAuthorizationDigest)
                    || p.authorizer == address(0)
                    || (p.authorizerKind != 1 && p.authorizerKind != 2)
            ) {
                revert InvalidPreparedNativeContentPurchase();
            }
        } else {
            revert InvalidPreparedNativeContentPurchase();
        }
    }

    /// @dev Signature/membership verification belongs to the independently admitted gate.
    /// These checks bind its signed presentation to the complete actual Manager batch.
    function requireAuthorization(
        IStreamMintManager.MintBatch calldata b,
        StreamPreparedNativeContentPurchaseTypes.GateData memory d,
        StreamPreparedNativeContentPurchaseTypes.Purchase memory p,
        StreamPreparedNativeSettlementTypes.Intent memory i
    ) public view {
        if (
            b.initialRecipients.length != 1 || b.beneficiaries.length != 1
                || b.tokenData.length != 1 || b.mintCommitments.length != 1
                || b.initialRecipients[0] != msg.sender || b.beneficiaries[0] != i.beneficiary
                || b.payer != p.buyer || b.authorizer != p.authorizer
                || b.authorizationId != p.authorizationId || d.authorizationId != p.authorizationId
                || b.collectionId != i.collectionId || b.phaseId != i.phaseId
                || b.expectedPolicyHash != i.boundMintPolicyHash
                || b.mintCommitments[0] != i.mintCommitment
        ) revert InvalidPreparedNativeContentPurchase();
        StreamPrivateSaleTypes.SaleAuthorization memory a = d.authorization;
        if (i.authorityMode == 2) {
            StreamPrivateSaleTypes.SaleAuthorization memory empty;
            if (
                keccak256(abi.encode(a)) != keccak256(abi.encode(empty))
                    || d.signature.authorizer != address(0) || d.signature.kind != 0
                    || d.signature.signature.length != 0
            ) revert InvalidPreparedNativeContentPurchase();
            return;
        }
        bytes32 digest = StreamPrivateSaleHash.digest(
            block.chainid, msg.sender, StreamPrivateSaleHash.authorizationBody(a)
        );
        if (
            a.chainId != block.chainid || a.saleAdapter != msg.sender
                || a.mintManager != address(this) || a.collectionId != b.collectionId
                || a.phaseId != b.phaseId || a.saleId != p.saleId || a.saleKind != 5
                || a.revenueClass != keccak256("PRIMARY_SALE") || a.primaryPolicyMode != 0
                || a.expectedPrimaryPolicyHash != i.originalPrimaryPolicyHash
                || a.primaryPolicyMode != i.primaryPolicyMode || a.payer != b.payer
                || a.executor != i.executor || a.asset != address(0) || a.unitPrice != i.amount
                || a.quantity != 1 || a.contentSelectionHash != i.contentSelectionHash
                || a.policyHash != b.expectedPolicyHash || a.nonce == 0
                || a.deadline < block.timestamp || a.finalizeBy != 0
                || digest != i.saleAuthorizationDigest || d.signature.authorizer != p.authorizer
                || d.signature.kind != p.authorizerKind
                || a.initialRecipientsHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_RECIPIENTS_V1"), b.initialRecipients
                        )
                    )
                || a.beneficiariesHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_BENEFICIARIES_V1"), b.beneficiaries
                        )
                    )
                || a.tokenDataArrayHash
                    != keccak256(
                        abi.encode(keccak256("6529STREAM_MINT_BATCH_TOKEN_DATA_V1"), b.tokenData)
                    )
                || a.mintCommitmentsHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_COMMITMENTS_V1"), b.mintCommitments
                        )
                    )
        ) revert InvalidPreparedNativeContentPurchase();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/mint/IStreamPreparedNativeContentPurchaseGate.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeContentMint.sol";
import "./StreamPreparedNativeContentHash.sol";
import "./StreamPreparedNativeContentPurchaseHash.sol";
import "./StreamMintGateValidator.sol";
import "../../vendor/openzeppelin/MerkleProof.sol";

/// @notice Independent original leaf/bytes correspondence and actual phase/counter selection.
library StreamPreparedNativeContentPurchaseReads {
    error InvalidPreparedNativeContent();

    function requirePublication(
        address manager,
        address registry,
        address house,
        uint256 collection,
        bytes32 phase,
        bytes32 saleId,
        bytes32 root
    )
        public
        view
        returns (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        )
    {
        IStreamMintManager m = IStreamMintManager(manager);
        g = m.phaseGate(collection, phase);
        if (g.gate == address(0) || g.gate.codehash != g.gateCodehash || root == 0) {
            revert InvalidPreparedNativeContent();
        }
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(g, IERC165(registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(g))) {
            revert InvalidPreparedNativeContent();
        }
        IStreamPreparedNativeContentPurchaseGate gate =
            IStreamPreparedNativeContentPurchaseGate(g.gate);
        p = gate.publication();
        if (
            !gate.supportsInterface(type(IStreamPreparedNativeContentPurchaseGate).interfaceId)
                || gate.contentPurchaseVersion()
                    != keccak256("6529STREAM_NATIVE_CONTENT_PURCHASE_GATE_V1")
                || gate.gateConfigHash() != g.gateConfigHash || p.chainId != block.chainid
                || p.manager != manager || p.house != house || p.collectionId != collection
                || p.phaseId != phase || p.saleId != saleId || p.manifestRoot != root
                || p.manifestHash == 0 || p.counterId == 0 || gate.itemCount() == 0
        ) revert InvalidPreparedNativeContent();
        if (
            g.gateConfigHash
                != keccak256(
                    abi.encode(
                        keccak256("6529STREAM_NATIVE_CONTENT_PURCHASE_GATE_V1"),
                        p,
                        manager.codehash,
                        house.codehash
                    )
                )
        ) revert InvalidPreparedNativeContent();
        requireManifest(gate, p);
        (bool exists, IStreamMintManager.MintPhaseConfig memory config) = m.phase(collection, phase);
        IStreamMintManager.MintCounterConfig memory counter =
            m.counterConfig(collection, phase, p.counterId);
        bytes32[] memory ids = m.phaseCounterIds(collection, phase);
        bool found;
        for (uint256 n; n < ids.length; ++n) {
            if (ids[n] == p.counterId) found = true;
        }
        if (
            !exists || config.paused || config.maxBatchQuantity != 1
                || !m.phaseExecutor(collection, phase, house) || !found || !counter.enabled
                || counter.keyMode != IStreamMintManager.CounterKeyMode.CONTEXT
                || counter.capMode != IStreamMintLedger.CounterCapMode.STATIC
                || counter.deltaMode != IStreamMintLedger.CounterDeltaMode.STATIC
                || counter.staticCap != 1 || counter.staticIncrement != 1
                || counter.counterConfigHash == 0
        ) revert InvalidPreparedNativeContent();
    }

    function requireManifest(
        IStreamPreparedNativeContentPurchaseGate gate,
        StreamPreparedNativeContentTypes.Publication memory p
    ) private view {
        bytes memory raw = gate.manifestBytes();
        StreamPreparedNativeContentTypes.Row[] memory rows =
            abi.decode(raw, (StreamPreparedNativeContentTypes.Row[]));
        if (
            rows.length == 0 || rows.length != gate.itemCount() || keccak256(raw) != p.manifestHash
                || keccak256(abi.encode(rows)) != p.manifestHash
        ) revert InvalidPreparedNativeContent();
        bytes32[] memory level = new bytes32[](rows.length);
        for (uint256 n; n < rows.length; ++n) {
            if (
                (n != 0 && rows[n - 1].contentId >= rows[n].contentId) || rows[n].tokenDataHash == 0
                    || bytes(rows[n].previewURI).length == 0
            ) revert InvalidPreparedNativeContent();
            level[n] = StreamPreparedNativeContentHash.leaf(
                p.chainId, p.house, p.saleId, rows[n].contentId, rows[n].tokenDataHash
            );
        }
        uint256 width = rows.length;
        while (width > 1) {
            uint256 next;
            for (uint256 n; n < width; n += 2) {
                bytes32 a = level[n];
                if (n + 1 == width) {
                    level[next] = a;
                } else {
                    bytes32 b = level[n + 1];
                    level[next] = a < b
                        ? keccak256(abi.encodePacked(a, b))
                        : keccak256(abi.encodePacked(b, a));
                }
                ++next;
            }
            width = next;
        }
        if (level[0] != p.manifestRoot) revert InvalidPreparedNativeContent();
    }

    function requireBatch(
        address registry,
        IStreamMintManager.MintBatch calldata b,
        bytes calldata gateData,
        bytes32 intentHash,
        StreamPreparedNativeSettlementTypes.Intent memory intent
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        if (b.tokenData.length != 1 || b.tokenData[0].length > 8192 || intentHash == 0) {
            revert InvalidPreparedNativeContent();
        }
        StreamPreparedNativeContentPurchaseTypes.GateData memory d =
            abi.decode(gateData, (StreamPreparedNativeContentPurchaseTypes.GateData));
        if (
            keccak256(gateData) != keccak256(abi.encode(d)) || d.intentHash != intentHash
                || d.selection.tokenDataHash != keccak256(b.tokenData[0])
        ) revert InvalidPreparedNativeContent();
        StreamPreparedNativeContentPurchaseTypes.Purchase memory purchase =
            StreamPreparedNativeContentPurchaseHash.readPurchase(msg.sender, intentHash, intent);
        StreamPreparedNativeContentPurchaseHash.requireAuthorization(b, d, purchase, intent);
        bytes32 saleId = intent.saleId;
        IStreamMintManager.MintGateConfig memory selected =
            IStreamMintManager(address(this)).phaseGate(b.collectionId, b.phaseId);
        StreamPreparedNativeContentTypes.Publication memory declared =
            IStreamPreparedNativeContentPurchaseGate(selected.gate).publication();
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            address(this),
            registry,
            msg.sender,
            b.collectionId,
            b.phaseId,
            saleId,
            declared.manifestRoot
        );
        c.gate = g.gate;
        c.gateCodeHash = g.gateCodehash;
        c.gateConfigHash = g.gateConfigHash;
        c.manifestRoot = p.manifestRoot;
        c.manifestHash = p.manifestHash;
        c.counterId = p.counterId;
        c.contentId = d.selection.contentId;
        c.tokenDataHash = d.selection.tokenDataHash;
        c.contentLeaf = StreamPreparedNativeContentHash.leaf(
            block.chainid, msg.sender, saleId, c.contentId, c.tokenDataHash
        );
        c.contextHash =
            StreamPreparedNativeContentHash.context(block.chainid, msg.sender, saleId, c.contentId);
        if (
            b.contextHash != c.contextHash
                || !MerkleProof.verify(d.selection.proof, c.manifestRoot, c.contentLeaf)
        ) revert InvalidPreparedNativeContent();
    }

    function requireActive(
        address registry,
        StreamPreparedNativeSettlementTypes.Facts memory f,
        StreamPreparedNativeSettlementTypes.Intent memory i
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        StreamPreparedNativeContentPurchaseTypes.Purchase memory purchase =
            StreamPreparedNativeContentPurchaseHash.readPurchase(f.saleAdapter, f.intentHash, i);
        c = IStreamPreparedNativeContentMint(f.mintManager).activePreparedNativeContent();
        uint256 operationRoot = uint256(c.operationRoot);
        c.operationRoot = 0;
        bytes32 admission = StreamPreparedNativeContentPurchaseHash.admissionHash(
            f.saleAdapter, f.intentHash, purchase, c
        );
        c.operationRoot = bytes32(operationRoot);
        if (
            IStreamPreparedNativeContentMint(f.mintManager).preparedNativeContentAdmission()
                != admission
        ) {
            revert InvalidPreparedNativeContent();
        }
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            f.mintManager,
            registry,
            f.saleAdapter,
            f.collectionId,
            f.phaseId,
            i.saleId,
            c.manifestRoot
        );
        if (
            c.operationRoot != f.operationRoot || c.operationRoot == 0 || c.gate != g.gate
                || c.gateCodeHash != g.gateCodehash || c.gateConfigHash != g.gateConfigHash
                || c.manifestHash != p.manifestHash || c.counterId != p.counterId
                || c.tokenDataHash != f.tokenDataHash || c.contentLeaf != i.contentSelectionHash
                || c.contentLeaf
                    != StreamPreparedNativeContentHash.leaf(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId, f.tokenDataHash
                    )
                || c.contextHash
                    != StreamPreparedNativeContentHash.context(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId
                    )
        ) revert InvalidPreparedNativeContent();
        IStreamMintManager m = IStreamMintManager(f.mintManager);
        bytes32 subject = m.previewSubjectKey(
            IStreamMintManager.CounterKeyMode.CONTEXT,
            f.collectionId,
            f.phaseId,
            c.counterId,
            f.payer,
            f.beneficiary,
            f.saleAdapter,
            purchase.authorizer,
            c.contextHash
        );
        bytes32 key = m.previewCounterValueKey(f.collectionId, f.phaseId, c.counterId, subject);
        (bool ok, bytes memory raw) =
            f.mintManager.staticcall(abi.encodeWithSignature("mintLedger()"));
        if (!ok || raw.length != 32) revert InvalidPreparedNativeContent();
        IStreamMintLedger ledger = IStreamMintLedger(abi.decode(raw, (address)));
        if (
            ledger.counterValue(key) != 1
                || !ledger.isManagerAuthorizationUsed(f.mintManager, purchase.authorizationId)
        ) {
            revert InvalidPreparedNativeContent();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/mint/IStreamNativeAuctionContentGate.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeContentMint.sol";
import "./StreamPreparedNativeContentHash.sol";
import "./StreamMintGateValidator.sol";
import "../../vendor/openzeppelin/MerkleProof.sol";

/// @notice Independent original leaf/bytes correspondence and actual phase/counter selection.
library StreamPreparedNativeContentReads {
    error InvalidPreparedNativeContent();

    function requirePublication(
        address manager,
        address registry,
        address house,
        uint256 collection,
        bytes32 phase,
        bytes32 saleId,
        bytes32 root
    )
        public
        view
        returns (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        )
    {
        IStreamMintManager m = IStreamMintManager(manager);
        g = m.phaseGate(collection, phase);
        if (g.gate == address(0) || g.gate.codehash != g.gateCodehash || root == 0) {
            revert InvalidPreparedNativeContent();
        }
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(g, IERC165(registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(g))) {
            revert InvalidPreparedNativeContent();
        }
        IStreamNativeAuctionContentGate gate = IStreamNativeAuctionContentGate(g.gate);
        p = gate.publication();
        if (
            !gate.supportsInterface(type(IStreamNativeAuctionContentGate).interfaceId)
                || gate.gateConfigHash() != g.gateConfigHash || p.chainId != block.chainid
                || p.manager != manager || p.house != house || p.collectionId != collection
                || p.phaseId != phase || p.saleId != saleId || p.manifestRoot != root
                || p.manifestHash == 0 || p.counterId == 0 || gate.itemCount() == 0
        ) revert InvalidPreparedNativeContent();
        if (
            g.gateConfigHash
                != keccak256(
                    abi.encode(
                        keccak256("6529STREAM_NATIVE_AUCTION_CONTENT_GATE_V1"),
                        p,
                        manager.codehash,
                        house.codehash
                    )
                )
        ) revert InvalidPreparedNativeContent();
        requireManifest(gate, p);
        (bool exists, IStreamMintManager.MintPhaseConfig memory config) = m.phase(collection, phase);
        IStreamMintManager.MintCounterConfig memory counter =
            m.counterConfig(collection, phase, p.counterId);
        bytes32[] memory ids = m.phaseCounterIds(collection, phase);
        bool found;
        for (uint256 n; n < ids.length; ++n) {
            if (ids[n] == p.counterId) found = true;
        }
        if (
            !exists || config.paused || config.maxBatchQuantity != 1
                || !m.phaseExecutor(collection, phase, house) || !found || !counter.enabled
                || counter.keyMode != IStreamMintManager.CounterKeyMode.CONTEXT
                || counter.capMode != IStreamMintLedger.CounterCapMode.STATIC
                || counter.deltaMode != IStreamMintLedger.CounterDeltaMode.STATIC
                || counter.staticCap != 1 || counter.staticIncrement != 1
                || counter.counterConfigHash == 0
        ) revert InvalidPreparedNativeContent();
    }

    function requireManifest(
        IStreamNativeAuctionContentGate gate,
        StreamPreparedNativeContentTypes.Publication memory p
    ) private view {
        bytes memory raw = gate.manifestBytes();
        StreamPreparedNativeContentTypes.Row[] memory rows =
            abi.decode(raw, (StreamPreparedNativeContentTypes.Row[]));
        if (
            rows.length == 0 || rows.length != gate.itemCount() || keccak256(raw) != p.manifestHash
                || keccak256(abi.encode(rows)) != p.manifestHash
        ) revert InvalidPreparedNativeContent();
        bytes32[] memory level = new bytes32[](rows.length);
        for (uint256 n; n < rows.length; ++n) {
            if (
                (n != 0 && rows[n - 1].contentId >= rows[n].contentId) || rows[n].tokenDataHash == 0
                    || bytes(rows[n].previewURI).length == 0
            ) revert InvalidPreparedNativeContent();
            level[n] = StreamPreparedNativeContentHash.leaf(
                p.chainId, p.house, p.saleId, rows[n].contentId, rows[n].tokenDataHash
            );
        }
        uint256 width = rows.length;
        while (width > 1) {
            uint256 next;
            for (uint256 n; n < width; n += 2) {
                bytes32 a = level[n];
                if (n + 1 == width) {
                    level[next] = a;
                } else {
                    bytes32 b = level[n + 1];
                    level[next] = a < b
                        ? keccak256(abi.encodePacked(a, b))
                        : keccak256(abi.encodePacked(b, a));
                }
                ++next;
            }
            width = next;
        }
        if (level[0] != p.manifestRoot) revert InvalidPreparedNativeContent();
    }

    function requireBatch(
        address registry,
        IStreamMintManager.MintBatch calldata b,
        bytes calldata gateData,
        bytes32 intentHash,
        bytes32 saleId
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        if (
            b.tokenData.length != 1 || b.tokenData[0].length > 8192
                || b.authorizationId != intentHash || intentHash == 0 || b.authorizer != address(0)
        ) revert InvalidPreparedNativeContent();
        StreamPreparedNativeContentTypes.GateData memory d =
            abi.decode(gateData, (StreamPreparedNativeContentTypes.GateData));
        if (
            keccak256(gateData) != keccak256(abi.encode(d)) || d.authorizationId != intentHash
                || d.selection.tokenDataHash != keccak256(b.tokenData[0])
        ) revert InvalidPreparedNativeContent();
        IStreamMintManager.MintGateConfig memory selected =
            IStreamMintManager(address(this)).phaseGate(b.collectionId, b.phaseId);
        StreamPreparedNativeContentTypes.Publication memory declared =
            IStreamNativeAuctionContentGate(selected.gate).publication();
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            address(this),
            registry,
            msg.sender,
            b.collectionId,
            b.phaseId,
            saleId,
            declared.manifestRoot
        );
        c.gate = g.gate;
        c.gateCodeHash = g.gateCodehash;
        c.gateConfigHash = g.gateConfigHash;
        c.manifestRoot = p.manifestRoot;
        c.manifestHash = p.manifestHash;
        c.counterId = p.counterId;
        c.contentId = d.selection.contentId;
        c.tokenDataHash = d.selection.tokenDataHash;
        c.contentLeaf = StreamPreparedNativeContentHash.leaf(
            block.chainid, msg.sender, saleId, c.contentId, c.tokenDataHash
        );
        c.contextHash =
            StreamPreparedNativeContentHash.context(block.chainid, msg.sender, saleId, c.contentId);
        if (
            b.contextHash != c.contextHash
                || !MerkleProof.verify(d.selection.proof, c.manifestRoot, c.contentLeaf)
        ) revert InvalidPreparedNativeContent();
    }

    function requireActive(
        address registry,
        StreamPreparedNativeSettlementTypes.Facts memory f,
        StreamPreparedNativeSettlementTypes.Intent memory i
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        c = IStreamPreparedNativeContentMint(f.mintManager).activePreparedNativeContent();
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            f.mintManager,
            registry,
            f.saleAdapter,
            f.collectionId,
            f.phaseId,
            i.saleId,
            c.manifestRoot
        );
        if (
            c.operationRoot != f.operationRoot || c.operationRoot == 0 || c.gate != g.gate
                || c.gateCodeHash != g.gateCodehash || c.gateConfigHash != g.gateConfigHash
                || c.manifestHash != p.manifestHash || c.counterId != p.counterId
                || c.tokenDataHash != f.tokenDataHash || c.contentLeaf != i.contentSelectionHash
                || c.contentLeaf
                    != StreamPreparedNativeContentHash.leaf(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId, f.tokenDataHash
                    )
                || c.contextHash
                    != StreamPreparedNativeContentHash.context(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId
                    )
        ) revert InvalidPreparedNativeContent();
        IStreamMintManager m = IStreamMintManager(f.mintManager);
        bytes32 subject = m.previewSubjectKey(
            IStreamMintManager.CounterKeyMode.CONTEXT,
            f.collectionId,
            f.phaseId,
            c.counterId,
            f.payer,
            f.beneficiary,
            f.saleAdapter,
            address(0),
            c.contextHash
        );
        bytes32 key = m.previewCounterValueKey(f.collectionId, f.phaseId, c.counterId, subject);
        (bool ok, bytes memory raw) =
            f.mintManager.staticcall(abi.encodeWithSignature("mintLedger()"));
        if (!ok || raw.length != 32) revert InvalidPreparedNativeContent();
        if (IStreamMintLedger(abi.decode(raw, (address))).counterValue(key) != 1) {
            revert InvalidPreparedNativeContent();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamMintRoyaltyPolicy } from "./StreamMintRoyaltyPolicy.sol";

import "../../interfaces/stream/mint/IStreamPreparedNativeMint.sol";
import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";
import "../revenue/StreamPreparedNativeSettlementValidation.sol";

/// @notice Typed paid preparation in Manager's storage/caller context, never an arbitrary hook.
library StreamPreparedNativeMintExecution {
    struct State {
        StreamPreparedNativeSettlementTypes.Facts active;
        address recorder;
        bytes32 recorderCodeHash;
        uint64 boundAt;
        uint64 moduleRevision;
    }

    struct Operation {
        IStreamCore core;
        address registry;
        bytes32 intentHash;
        bytes32 operationRoot;
        bytes32 operationId;
        bytes32 currentPolicyHash;
        bytes32 boundPolicyHash;
        uint256 callbackGas;
    }

    event PreparedMintStarted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        uint256 collectionSerial,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    event PreparedMintCompleted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        address initialRecipient
    );

    function bindRecorder(State storage state, address core, address registry, address recorder)
        public
    {
        if (state.recorder != address(0)) {
            revert IStreamPreparedNativeMint.PreparedNativeRecorderAlreadyBound();
        }
        (uint64 boundAt, uint64 revision) =
            StreamPreparedNativeSettlementAdmission.captureRecorder(registry, recorder);
        if (
            StreamPreparedNativeSettlementValidation.addressWord(recorder, "core()") != core
                || StreamPreparedNativeSettlementValidation.addressWord(
                        recorder, "moduleRegistry()"
                    ) != registry
                || StreamPreparedNativeSettlementValidation.word(recorder, "coreCodeHash()")
                    != core.codehash
                || StreamPreparedNativeSettlementValidation.word(
                        recorder, "moduleRegistryCodeHash()"
                    ) != registry.codehash
        ) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        StreamSettlementAdmission.requireRegistry(core, core.codehash, registry, registry.codehash);
        state.recorder = recorder;
        state.recorderCodeHash = recorder.codehash;
        state.boundAt = boundAt;
        state.moduleRevision = revision;
    }

    function execute(
        State storage state,
        IStreamMintManager.MintBatch calldata batch,
        Operation memory op
    )
        public
        returns (
            uint256 tokenId,
            StreamPrimarySettlementTypes.PrimarySettlementResult memory result
        )
    {
        if (
            state.recorder == address(0) || state.active.operationRoot != 0
                || batch.initialRecipients.length != 1 || batch.initialRecipients[0] != msg.sender
                || batch.tokenData[0].length > 8192 || op.intentHash == 0
                || batch.contextHash
                    != StreamPreparedNativeSettlementHash.mintContext(
                        address(this), msg.sender, op.intentHash
                    )
        ) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        StreamPreparedNativeSettlementAdmission.requireModule(op.registry, msg.sender);
        StreamPreparedNativeSettlementTypes.Facts memory f;
        f.saleAdapter = msg.sender;
        f.mintManager = address(this);
        f.recorder = StreamPreparedNativeSettlementValidation.addressWord(
            msg.sender, "primarySaleSettlement()"
        );
        f.recorderCodeHash =
            StreamPreparedNativeSettlementValidation.word(msg.sender, "settlementCodeHash()");
        f.collectionId = batch.collectionId;
        f.phaseId = batch.phaseId;
        f.intentHash = op.intentHash;
        f.operationRoot = op.operationRoot;
        f.operationId = op.operationId;
        f.payer = batch.payer;
        f.initialRecipient = batch.initialRecipients[0];
        f.beneficiary = batch.beneficiaries[0];
        f.tokenDataHash = keccak256(batch.tokenData[0]);
        f.mintCommitment = batch.mintCommitments[0];
        f.currentPolicyHash = op.currentPolicyHash;
        f.boundPolicyHash = op.boundPolicyHash;
        StreamPreparedNativeSettlementTypes.Intent memory intent =
            StreamPreparedNativeSettlementValidation.readIntent(
                msg.sender, f.recorder, f.intentHash
            );
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, intent.saleId
        );
        StreamPreparedNativeSettlementValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        StreamPreparedNativeSettlementValidation.requireIntentFields(f, intent);
        (f.tokenId, f.collectionSerial) = op.core
            .prepareMintFromManager(
                batch.collectionId, batch.tokenData[0], f.tokenDataHash, f.operationId
            );
        state.active = f;
        StreamMintRoyaltyPolicy.snapshot(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintStarted(
            1,
            f.operationId,
            f.tokenId,
            f.collectionId,
            f.operationRoot,
            f.collectionSerial,
            f.beneficiary,
            f.tokenDataHash,
            f.mintCommitment
        );
        result = _callback(f, op.callbackGas);
        _requireResult(f, intent, result);
        StreamPreparedNativeSettlementValidation.requireActive(
            address(op.core), op.registry, f, intent
        );
        op.core
            .completePreparedMintFromManager(
                f.tokenId, f.initialRecipient, f.operationId, f.mintCommitment
            );
        _requireResult(f, intent, result);
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, intent.saleId
        );
        StreamPreparedNativeSettlementValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        if (
            op.core.ownerOf(f.tokenId) != f.initialRecipient
                || op.core.pendingPreparedMintTokenId() != 0
                || op.core.tokenLifecycle(f.tokenId) != 2
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        StreamMintRoyaltyPolicy.completed(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintCompleted(
            1, f.operationId, f.tokenId, f.collectionId, f.operationRoot, f.initialRecipient
        );
        tokenId = f.tokenId;
        delete state.active;
    }

    function _callback(StreamPreparedNativeSettlementTypes.Facts memory facts, uint256 cap)
        private
        returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result)
    {
        bytes memory data =
            abi.encodeCall(IStreamPreparedNativeSaleBinding.onPreparedNativeMint, (facts));
        bytes memory raw = new bytes(416);
        uint256 available = gasleft();
        if (cap == 0 || cap > type(uint64).max) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        uint256 required = cap + cap / 63 + 1_000_000;
        if (available <= required) {
            revert IStreamPreparedNativeMint.InsufficientPreparedNativeGas(available, required);
        }
        address sale = facts.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(cap, sale, 0, add(data, 32), mload(data), add(raw, 32), 416)
            size := returndatasize()
        }
        if (!ok || size != 416) {
            revert IStreamPreparedNativeMint.PreparedNativeCallFailed(
                sale, IStreamPreparedNativeSaleBinding.onPreparedNativeMint.selector
            );
        }
        bytes4 magic;
        (magic, result) =
            abi.decode(raw, (bytes4, StreamPrimarySettlementTypes.PrimarySettlementResult));
        if (
            magic != IStreamPreparedNativeSaleBinding.onPreparedNativeMint.selector
                || keccak256(raw) != keccak256(abi.encode(magic, result))
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }

    function _requireResult(
        StreamPreparedNativeSettlementTypes.Facts memory f,
        StreamPreparedNativeSettlementTypes.Intent memory intent,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory result
    ) private view {
        if (f.recorder.codehash != f.recorderCodeHash) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementResult, (result.settlementKey)),
            384
        );
        if (
            keccak256(raw) != keccak256(abi.encode(result)) || result.candidateCommitment == 0
                || result.settlementKey == 0 || result.profileId == 0 || result.wallet == address(0)
                || result.asset != address(0) || result.amount != intent.amount
                || result.executor != intent.executor
                || result.executionId != StreamPreparedNativeSettlementHash.executionId(f, intent)
                || result.operationIdentityCommitment != f.operationRoot
                || result.currentPolicyHash != f.currentPolicyHash
                || result.boundPolicyHash != f.boundPolicyHash
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(
                IStreamPreparedNativePrimarySaleSettlement.preparedNativeFactsHash,
                (result.settlementKey)
            ),
            32
        );
        if (abi.decode(raw, (bytes32)) != StreamPreparedNativeSettlementHash.factsHash(f)) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementConsumed, (result.settlementKey)),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }
}

