pragma solidity ^0.8.19;

import {
    IStreamPreparedNativeOfferSale
} from "../../interfaces/stream/mint/IStreamPreparedNativeOfferMint.sol";
import {
    StreamPreparedNativeOfferTypes as Offer
} from "../../interfaces/stream/mint/StreamPreparedNativeOfferTypes.sol";
import {
    StreamPreparedNativeContentTypes as Content
} from "../../interfaces/stream/mint/StreamPreparedNativeContentTypes.sol";
import {
    StreamPreparedNativeSettlementTypes as Prepared
} from "../../interfaces/stream/revenue/StreamPreparedNativeSettlementTypes.sol";
import { IStreamMintManager } from "../../interfaces/stream/mint/IStreamMintManager.sol";
import { IStreamMintReads } from "../../interfaces/stream/mint/IStreamMintReads.sol";
import { StreamPrivateSaleTypes } from "../../interfaces/stream/mint/StreamPrivateSaleTypes.sol";
import { StreamPrivateSaleHash } from "./StreamPrivateSaleHash.sol";
import { StreamMintTicketHash } from "./StreamMintTicketHash.sol";

/// @notice Original buyer offer replay key and seller authorization under a distinct offer admission.
library StreamPreparedNativeOfferHash {
    error InvalidPreparedNativeOffer();

    function purchaseId(address house, bytes32 saleId, address buyer, uint256 nonce)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_SALE_PURCHASE_V1"), block.chainid, house, saleId, buyer, nonce
            )
        );
    }

    function intentHash(address house, address recorder, Prepared.Intent memory intent)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PREPARED_NATIVE_OFFER_INTENT_V1"),
                block.chainid,
                house,
                recorder,
                intent
            )
        );
    }

    function admissionHash(
        address house,
        bytes32 hash,
        Offer.Purchase memory purchase,
        Content.Facts memory content
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PREPARED_NATIVE_OFFER_ADMISSION_V1"),
                block.chainid,
                house,
                hash,
                purchase,
                content
            )
        );
    }

    function readPurchase(address house, bytes32 hash, Prepared.Intent memory i)
        public
        view
        returns (Offer.Purchase memory p)
    {
        bytes memory input = abi.encodeCall(
            IStreamPreparedNativeOfferSale.activePreparedNativeOfferPurchase, (hash)
        );
        bytes memory raw = new bytes(352);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), house, add(input, 32), mload(input), add(raw, 32), 352)
            size := returndatasize()
        }
        if (!ok || size != 352) revert InvalidPreparedNativeOffer();
        p = abi.decode(raw, (Offer.Purchase));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || hash == 0 || house == address(0)
                || p.saleId == 0 || p.saleId != i.saleId || p.saleNonce == 0
                || p.saleNonce != i.saleNonce || p.saleConfigHash == 0 || p.buyer == address(0)
                || p.buyer != i.payer || p.buyer != i.beneficiary || p.purchaseNonce == 0
                || p.purchaseNonce != i.executionNonce
                || p.purchaseId != purchaseId(house, p.saleId, p.buyer, p.purchaseNonce)
                || p.primaryPolicyMode != 0 || i.primaryPolicyMode != 0 || i.authorityMode != 1
                || i.amount == 0 || i.saleAuthorizationDigest == 0 || p.offerDigest == 0
                || p.authorizationId != StreamMintTicketHash.authorizationId(p.offerDigest)
                || p.authorizer == address(0) || (p.authorizerKind != 1 && p.authorizerKind != 2)
        ) revert InvalidPreparedNativeOffer();
    }

    /// @dev Also used by the selected gate, which independently authenticates both full digests.
    function requirePresentation(
        address manager,
        address house,
        Offer.GateData memory d,
        Offer.Purchase memory p,
        Prepared.Intent memory i
    ) public view {
        StreamPrivateSaleTypes.SaleAuthorization memory a = d.authorization;
        StreamPrivateSaleTypes.SaleOffer memory o = d.offer;
        bytes32 sellerDigest = StreamPrivateSaleHash.digest(
            block.chainid, house, StreamPrivateSaleHash.authorizationBody(a)
        );
        bytes32 buyerDigest =
            StreamPrivateSaleHash.digest(block.chainid, house, StreamPrivateSaleHash.offerBody(o));
        if (
            i.authorityMode != 1 || i.primaryPolicyMode != 0 || i.amount == 0 || i.payer != p.buyer
                || i.beneficiary != p.buyer || d.authorizationId != p.authorizationId
                || p.primaryPolicyMode != 0 || p.offerDigest != buyerDigest
                || p.authorizationId != StreamMintTicketHash.authorizationId(buyerDigest)
                || sellerDigest != i.saleAuthorizationDigest
                || d.buyerSignature.authorizer != p.authorizer
                || d.buyerSignature.kind != p.authorizerKind || a.chainId != block.chainid
                || a.saleAdapter != house || a.mintManager != manager
                || a.collectionId != i.collectionId || a.phaseId != i.phaseId
                || a.saleId != p.saleId || a.saleKind != 6
                || a.revenueClass != keccak256("PRIMARY_SALE")
                || a.expectedPrimaryPolicyHash != i.originalPrimaryPolicyHash
                || a.primaryPolicyMode != 0 || a.payer != p.buyer || a.executor != i.executor
                || a.asset != address(0) || a.unitPrice != i.amount || a.quantity != 1
                || a.contentSelectionHash != i.contentSelectionHash
                || a.policyHash != i.boundMintPolicyHash || a.nonce == 0
                || a.deadline < block.timestamp || a.finalizeBy != 0 || o.chainId != block.chainid
                || o.saleAdapter != house || o.core != address(IStreamMintReads(manager).core())
                || o.collectionId != i.collectionId || o.tokenId != 0 || o.buyer != p.buyer
                || o.contentSelectionHash != i.contentSelectionHash || o.asset != address(0)
                || o.price != i.amount || o.nonce == 0 || o.deadline < block.timestamp
                || o.finalizeBy != 0
        ) revert InvalidPreparedNativeOffer();
    }

    function requireAuthorization(
        IStreamMintManager.MintBatch calldata b,
        Offer.GateData memory d,
        Offer.Purchase memory p,
        Prepared.Intent memory i
    ) public view {
        requirePresentation(address(this), msg.sender, d, p, i);
        if (
            b.initialRecipients.length != 1 || b.beneficiaries.length != 1
                || b.tokenData.length != 1 || b.mintCommitments.length != 1
                || b.initialRecipients[0] != msg.sender || b.beneficiaries[0] != p.buyer
                || b.payer != p.buyer || b.authorizer != p.authorizer
                || b.authorizationId != p.authorizationId || b.collectionId != i.collectionId
                || b.phaseId != i.phaseId || b.expectedPolicyHash != i.boundMintPolicyHash
                || b.mintCommitments[0] != i.mintCommitment
                || d.authorization.initialRecipientsHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_RECIPIENTS_V1"), b.initialRecipients
                        )
                    )
                || d.authorization.beneficiariesHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_BENEFICIARIES_V1"), b.beneficiaries
                        )
                    )
                || d.authorization.tokenDataArrayHash
                    != keccak256(
                        abi.encode(keccak256("6529STREAM_MINT_BATCH_TOKEN_DATA_V1"), b.tokenData)
                    )
                || d.authorization.mintCommitmentsHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_MINT_BATCH_COMMITMENTS_V1"), b.mintCommitments
                        )
                    )
        ) revert InvalidPreparedNativeOffer();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/mint/IStreamPreparedNativeOfferGate.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeOfferMint.sol";
import "./StreamPreparedNativeContentHash.sol";
import "./StreamPreparedNativeOfferHash.sol";
import "./StreamMintGateValidator.sol";
import "./StreamNativePrimaryOfferSignatures.sol";
import "../revenue/StreamPreparedNativeSettlementHash.sol";
import "../../vendor/openzeppelin/MerkleProof.sol";

/// @notice Independent original leaf/bytes correspondence and actual phase/counter selection.
library StreamPreparedNativeOfferReads {
    error InvalidPreparedNativeOfferContent();

    function requirePublication(
        address manager,
        address registry,
        address house,
        uint256 collection,
        bytes32 phase,
        bytes32 saleId,
        bytes32 root
    )
        public
        view
        returns (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        )
    {
        IStreamMintManager m = IStreamMintManager(manager);
        g = m.phaseGate(collection, phase);
        if (g.gate == address(0) || g.gate.codehash != g.gateCodehash || root == 0) {
            revert InvalidPreparedNativeOfferContent();
        }
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(g, IERC165(registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(g))) {
            revert InvalidPreparedNativeOfferContent();
        }
        IStreamPreparedNativeOfferGate gate = IStreamPreparedNativeOfferGate(g.gate);
        p = gate.publication();
        if (
            !gate.supportsInterface(type(IStreamPreparedNativeOfferGate).interfaceId)
                || gate.offerPurchaseVersion()
                    != keccak256("6529STREAM_NATIVE_PRIMARY_OFFER_GATE_V1")
                || gate.gateConfigHash() != g.gateConfigHash || p.chainId != block.chainid
                || p.manager != manager || p.house != house || p.collectionId != collection
                || p.phaseId != phase || p.saleId != saleId || p.manifestRoot != root
                || p.manifestHash == 0 || p.counterId == 0 || gate.itemCount() == 0
        ) revert InvalidPreparedNativeOfferContent();
        if (
            g.gateConfigHash
                != keccak256(
                    abi.encode(
                        keccak256("6529STREAM_NATIVE_PRIMARY_OFFER_GATE_V1"),
                        p,
                        manager.codehash,
                        house.codehash
                    )
                )
        ) revert InvalidPreparedNativeOfferContent();
        requireManifest(gate, p);
        (bool exists, IStreamMintManager.MintPhaseConfig memory config) = m.phase(collection, phase);
        IStreamMintManager.MintCounterConfig memory counter =
            m.counterConfig(collection, phase, p.counterId);
        bytes32[] memory ids = m.phaseCounterIds(collection, phase);
        bool found;
        for (uint256 n; n < ids.length; ++n) {
            if (ids[n] == p.counterId) found = true;
        }
        if (
            !exists || config.paused || config.maxBatchQuantity != 1
                || !m.phaseExecutor(collection, phase, house) || !found || !counter.enabled
                || counter.keyMode != IStreamMintManager.CounterKeyMode.CONTEXT
                || counter.capMode != IStreamMintLedger.CounterCapMode.STATIC
                || counter.deltaMode != IStreamMintLedger.CounterDeltaMode.STATIC
                || counter.staticCap != 1 || counter.staticIncrement != 1
                || counter.counterConfigHash == 0
        ) revert InvalidPreparedNativeOfferContent();
    }

    function requireManifest(
        IStreamPreparedNativeOfferGate gate,
        StreamPreparedNativeContentTypes.Publication memory p
    ) private view {
        bytes memory raw = gate.manifestBytes();
        StreamPreparedNativeContentTypes.Row[] memory rows =
            abi.decode(raw, (StreamPreparedNativeContentTypes.Row[]));
        if (
            rows.length == 0 || rows.length != gate.itemCount() || keccak256(raw) != p.manifestHash
                || keccak256(abi.encode(rows)) != p.manifestHash
        ) revert InvalidPreparedNativeOfferContent();
        bytes32[] memory level = new bytes32[](rows.length);
        for (uint256 n; n < rows.length; ++n) {
            if (
                (n != 0 && rows[n - 1].contentId >= rows[n].contentId) || rows[n].tokenDataHash == 0
                    || bytes(rows[n].previewURI).length == 0
            ) revert InvalidPreparedNativeOfferContent();
            level[n] = StreamPreparedNativeContentHash.leaf(
                p.chainId, p.house, p.saleId, rows[n].contentId, rows[n].tokenDataHash
            );
        }
        uint256 width = rows.length;
        while (width > 1) {
            uint256 next;
            for (uint256 n; n < width; n += 2) {
                bytes32 a = level[n];
                if (n + 1 == width) {
                    level[next] = a;
                } else {
                    bytes32 b = level[n + 1];
                    level[next] = a < b
                        ? keccak256(abi.encodePacked(a, b))
                        : keccak256(abi.encodePacked(b, a));
                }
                ++next;
            }
            width = next;
        }
        if (level[0] != p.manifestRoot) revert InvalidPreparedNativeOfferContent();
    }

    function requireBatch(
        address registry,
        IStreamMintManager.MintBatch calldata b,
        bytes calldata gateData,
        bytes32 intentHash,
        StreamPreparedNativeSettlementTypes.Intent memory intent
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        if (b.tokenData.length != 1 || b.tokenData[0].length > 8192 || intentHash == 0) {
            revert InvalidPreparedNativeOfferContent();
        }
        StreamPreparedNativeOfferTypes.GateData memory d =
            abi.decode(gateData, (StreamPreparedNativeOfferTypes.GateData));
        if (keccak256(gateData) != keccak256(abi.encode(d)) || d.intentHash != intentHash) {
            revert InvalidPreparedNativeOfferContent();
        }
        StreamPreparedNativeOfferTypes.Purchase memory purchase =
            StreamPreparedNativeOfferHash.readPurchase(msg.sender, intentHash, intent);
        StreamPreparedNativeOfferHash.requireAuthorization(b, d, purchase, intent);
        IStreamMintManager.MintGateConfig memory selected =
            IStreamMintManager(address(this)).phaseGate(b.collectionId, b.phaseId);
        if (selected.gate == address(0)) {
            _requireNoGate(selected);
            if (
                d.selection.contentId != 0 || d.selection.tokenDataHash != 0
                    || d.selection.proof.length != 0 || intent.contentSelectionHash != 0
            ) revert InvalidPreparedNativeOfferContent();
            c.tokenDataHash = keccak256(b.tokenData[0]);
            c.contextHash = StreamPreparedNativeSettlementHash.mintContext(
                address(this), msg.sender, intentHash
            );
            if (b.contextHash != c.contextHash) revert InvalidPreparedNativeOfferContent();
            StreamNativePrimaryOfferSignatures.validate(
                address(this), msg.sender, d, purchase, intent
            );
            return c;
        }
        if (d.selection.tokenDataHash != keccak256(b.tokenData[0])) {
            revert InvalidPreparedNativeOfferContent();
        }
        StreamPreparedNativeContentTypes.Publication memory declared =
            IStreamPreparedNativeOfferGate(selected.gate).publication();
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            address(this),
            registry,
            msg.sender,
            b.collectionId,
            b.phaseId,
            intent.saleId,
            declared.manifestRoot
        );
        c.gate = g.gate;
        c.gateCodeHash = g.gateCodehash;
        c.gateConfigHash = g.gateConfigHash;
        c.manifestRoot = p.manifestRoot;
        c.manifestHash = p.manifestHash;
        c.counterId = p.counterId;
        c.contentId = d.selection.contentId;
        c.tokenDataHash = d.selection.tokenDataHash;
        c.contentLeaf = StreamPreparedNativeContentHash.leaf(
            block.chainid, msg.sender, intent.saleId, c.contentId, c.tokenDataHash
        );
        c.contextHash = StreamPreparedNativeContentHash.context(
            block.chainid, msg.sender, intent.saleId, c.contentId
        );
        if (
            b.contextHash != c.contextHash || c.contentLeaf != intent.contentSelectionHash
                || !MerkleProof.verify(d.selection.proof, c.manifestRoot, c.contentLeaf)
        ) revert InvalidPreparedNativeOfferContent();
    }

    function requireActive(
        address registry,
        StreamPreparedNativeSettlementTypes.Facts memory f,
        StreamPreparedNativeSettlementTypes.Intent memory i
    ) public view returns (StreamPreparedNativeContentTypes.Facts memory c) {
        StreamPreparedNativeOfferTypes.Purchase memory purchase =
            StreamPreparedNativeOfferHash.readPurchase(f.saleAdapter, f.intentHash, i);
        c = IStreamPreparedNativeOfferMint(f.mintManager).activePreparedNativeOfferContent();
        bytes32 root = c.operationRoot;
        c.operationRoot = 0;
        bytes32 admission =
            StreamPreparedNativeOfferHash.admissionHash(f.saleAdapter, f.intentHash, purchase, c);
        c.operationRoot = root;
        if (
            IStreamPreparedNativeOfferMint(f.mintManager).preparedNativeOfferAdmission()
                    != admission || root == 0 || root != f.operationRoot
                || c.tokenDataHash != f.tokenDataHash
        ) revert InvalidPreparedNativeOfferContent();
        IStreamMintManager m = IStreamMintManager(f.mintManager);
        IStreamMintManager.MintGateConfig memory selected = m.phaseGate(f.collectionId, f.phaseId);
        IStreamMintLedger ledger = _ledger(f.mintManager);
        if (!ledger.isManagerAuthorizationUsed(f.mintManager, purchase.authorizationId)) {
            revert InvalidPreparedNativeOfferContent();
        }
        if (selected.gate == address(0)) {
            _requireNoGate(selected);
            StreamPreparedNativeContentTypes.Facts memory empty;
            empty.operationRoot = f.operationRoot;
            empty.tokenDataHash = f.tokenDataHash;
            empty.contextHash = StreamPreparedNativeSettlementHash.mintContext(
                f.mintManager, f.saleAdapter, f.intentHash
            );
            if (
                i.contentSelectionHash != 0
                    || keccak256(abi.encode(c)) != keccak256(abi.encode(empty))
            ) revert InvalidPreparedNativeOfferContent();
            return c;
        }
        (
            IStreamMintManager.MintGateConfig memory g,
            StreamPreparedNativeContentTypes.Publication memory p
        ) = requirePublication(
            f.mintManager,
            registry,
            f.saleAdapter,
            f.collectionId,
            f.phaseId,
            i.saleId,
            c.manifestRoot
        );
        if (
            c.gate != g.gate || c.gateCodeHash != g.gateCodehash
                || c.gateConfigHash != g.gateConfigHash || c.manifestHash != p.manifestHash
                || c.counterId != p.counterId || c.contentLeaf != i.contentSelectionHash
                || c.contentLeaf
                    != StreamPreparedNativeContentHash.leaf(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId, f.tokenDataHash
                    )
                || c.contextHash
                    != StreamPreparedNativeContentHash.context(
                        block.chainid, f.saleAdapter, i.saleId, c.contentId
                    )
        ) revert InvalidPreparedNativeOfferContent();
        bytes32 subject = m.previewSubjectKey(
            IStreamMintManager.CounterKeyMode.CONTEXT,
            f.collectionId,
            f.phaseId,
            c.counterId,
            f.payer,
            f.beneficiary,
            f.saleAdapter,
            purchase.authorizer,
            c.contextHash
        );
        bytes32 key = m.previewCounterValueKey(f.collectionId, f.phaseId, c.counterId, subject);
        if (ledger.counterValue(key) != 1) revert InvalidPreparedNativeOfferContent();
    }

    function _requireNoGate(IStreamMintManager.MintGateConfig memory g) private pure {
        IStreamMintManager.MintGateConfig memory empty;
        if (keccak256(abi.encode(g)) != keccak256(abi.encode(empty))) {
            revert InvalidPreparedNativeOfferContent();
        }
    }

    function _ledger(address manager) private view returns (IStreamMintLedger) {
        bytes memory data = abi.encodeWithSignature("mintLedger()");
        bool ok;
        uint256 size;
        uint256 value;
        assembly ("memory-safe") {
            ok := staticcall(gas(), manager, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            value := mload(0)
        }
        if (!ok || size != 32 || value == 0 || value > type(uint160).max) {
            revert InvalidPreparedNativeOfferContent();
        }
        return IStreamMintLedger(address(uint160(value)));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamMintRoyaltyPolicy } from "./StreamMintRoyaltyPolicy.sol";

import "../../interfaces/stream/mint/IStreamPreparedNativeMint.sol";
import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";
import "../revenue/StreamPreparedNativeRightsValidation.sol";
import "./StreamPreparedNativeMintExecution.sol";

/// @notice Typed paid preparation in Manager's storage/caller context, never an arbitrary hook.
library StreamPreparedNativeRightsExecution {
    struct State {
        StreamPreparedNativeRightsTypes.Facts active;
    }

    struct Operation {
        IStreamCore core;
        address registry;
        bytes32 intentHash;
        bytes32 operationRoot;
        bytes32 operationId;
        bytes32 currentPolicyHash;
        bytes32 boundPolicyHash;
        uint256 callbackGas;
    }

    event PreparedMintStarted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        uint256 collectionSerial,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    event PreparedMintCompleted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        address initialRecipient
    );

    function execute(
        State storage state,
        StreamPreparedNativeMintExecution.State storage recorderState,
        IStreamMintManager.MintBatch calldata batch,
        Operation memory op
    )
        public
        returns (
            uint256 tokenId,
            StreamPrimarySettlementTypes.PrimarySettlementResult memory result
        )
    {
        if (
            recorderState.recorder == address(0) || recorderState.active.operationRoot != 0
                || state.active.mint.operationRoot != 0 || batch.initialRecipients.length != 1
                || batch.initialRecipients[0] != msg.sender || batch.tokenData[0].length > 8192
                || op.intentHash == 0 || batch.authorizationId != op.intentHash
                || batch.contextHash
                    != StreamPreparedNativeRightsHash.mintContext(
                        address(this), msg.sender, op.intentHash
                    )
        ) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        StreamPreparedNativeSettlementAdmission.requireModule(op.registry, msg.sender);
        StreamPreparedNativeSettlementTypes.Facts memory f;
        f.saleAdapter = msg.sender;
        f.mintManager = address(this);
        f.recorder = StreamPreparedNativeSettlementValidation.addressWord(
            msg.sender, "primarySaleSettlement()"
        );
        f.recorderCodeHash =
            StreamPreparedNativeSettlementValidation.word(msg.sender, "settlementCodeHash()");
        f.collectionId = batch.collectionId;
        f.phaseId = batch.phaseId;
        f.intentHash = op.intentHash;
        f.operationRoot = op.operationRoot;
        f.operationId = op.operationId;
        f.payer = batch.payer;
        f.initialRecipient = batch.initialRecipients[0];
        f.beneficiary = batch.beneficiaries[0];
        f.tokenDataHash = keccak256(batch.tokenData[0]);
        f.mintCommitment = batch.mintCommitments[0];
        f.currentPolicyHash = op.currentPolicyHash;
        f.boundPolicyHash = op.boundPolicyHash;
        StreamPreparedNativeRightsTypes.Intent memory original =
            StreamPreparedNativeRightsValidation.readIntent(msg.sender, f.recorder, f.intentHash);
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, original.sale.saleId
        );
        StreamPreparedNativeRightsValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        StreamPreparedNativeRightsTypes.Facts memory rights;
        rights.mint = f;
        rights.original = original.original;
        StreamPreparedNativeRightsValidation.requireIntentFields(rights, original);
        (f.tokenId, f.collectionSerial) = op.core
            .prepareMintFromManager(
                batch.collectionId, batch.tokenData[0], f.tokenDataHash, f.operationId
            );
        rights.mint = f;
        state.active = rights;
        StreamMintRoyaltyPolicy.snapshot(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintStarted(
            1,
            f.operationId,
            f.tokenId,
            f.collectionId,
            f.operationRoot,
            f.collectionSerial,
            f.beneficiary,
            f.tokenDataHash,
            f.mintCommitment
        );
        result = _callback(rights, op.callbackGas);
        _requireResult(rights, original, result);
        StreamPreparedNativeRightsValidation.requireActive(
            address(op.core), op.registry, rights, original
        );
        op.core
            .completePreparedMintFromManager(
                f.tokenId, f.initialRecipient, f.operationId, f.mintCommitment
            );
        _requireResult(rights, original, result);
        StreamPreparedNativeSettlementAdmission.requireAdmission(
            op.registry, msg.sender, original.sale.saleId
        );
        StreamPreparedNativeRightsValidation.requireBindings(
            address(op.core), op.registry, address(this), msg.sender, f.recorder, f.recorderCodeHash
        );
        if (
            op.core.ownerOf(f.tokenId) != f.initialRecipient
                || op.core.pendingPreparedMintTokenId() != 0
                || op.core.tokenLifecycle(f.tokenId) != 2
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        StreamMintRoyaltyPolicy.completed(
            StreamMintRoyaltyPolicy.Context(address(op.core), op.registry),
            f.collectionId,
            f.phaseId,
            f.tokenId,
            f.operationRoot,
            f.operationId
        );
        emit PreparedMintCompleted(
            1, f.operationId, f.tokenId, f.collectionId, f.operationRoot, f.initialRecipient
        );
        tokenId = f.tokenId;
        delete state.active;
    }

    function _callback(StreamPreparedNativeRightsTypes.Facts memory facts, uint256 cap)
        private
        returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result)
    {
        bytes memory data = abi.encodeCall(
            IStreamPreparedNativeRightsSaleBinding.onPreparedNativeRightsMint, (facts)
        );
        bytes memory raw = new bytes(416);
        uint256 available = gasleft();
        if (cap == 0 || cap > type(uint64).max) {
            revert IStreamPreparedNativeMint.InvalidPreparedNativeMint();
        }
        uint256 required = cap + cap / 63 + 1_000_000;
        if (available <= required) {
            revert IStreamPreparedNativeMint.InsufficientPreparedNativeGas(available, required);
        }
        address sale = facts.mint.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(cap, sale, 0, add(data, 32), mload(data), add(raw, 32), 416)
            size := returndatasize()
        }
        if (!ok || size != 416) {
            revert IStreamPreparedNativeMint.PreparedNativeCallFailed(
                sale, IStreamPreparedNativeRightsSaleBinding.onPreparedNativeRightsMint.selector
            );
        }
        bytes4 magic;
        (magic, result) =
            abi.decode(raw, (bytes4, StreamPrimarySettlementTypes.PrimarySettlementResult));
        if (
            magic != IStreamPreparedNativeRightsSaleBinding.onPreparedNativeRightsMint.selector
                || keccak256(raw) != keccak256(abi.encode(magic, result))
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }

    function _requireResult(
        StreamPreparedNativeRightsTypes.Facts memory rights,
        StreamPreparedNativeRightsTypes.Intent memory original,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory result
    ) private view {
        StreamPreparedNativeSettlementTypes.Facts memory f = rights.mint;
        StreamPreparedNativeSettlementTypes.Intent memory intent = original.sale;
        if (f.recorder.codehash != f.recorderCodeHash) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementResult, (result.settlementKey)),
            384
        );
        if (
            keccak256(raw) != keccak256(abi.encode(result)) || result.candidateCommitment == 0
                || result.settlementKey == 0 || result.profileId == 0 || result.wallet == address(0)
                || result.asset != address(0) || result.amount != intent.amount
                || result.executor != intent.executor
                || result.executionId
                    != StreamPreparedNativeRightsHash.executionId(rights, original)
                || result.operationIdentityCommitment != f.operationRoot
                || result.currentPolicyHash != f.currentPolicyHash
                || result.boundPolicyHash != f.boundPolicyHash
        ) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(
                IStreamPreparedNativeRightsPrimarySettlement.preparedNativeRightsFactsHash,
                (result.settlementKey)
            ),
            32
        );
        if (abi.decode(raw, (bytes32)) != StreamPreparedNativeRightsHash.factsHash(rights)) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            f.recorder,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementConsumed, (result.settlementKey)),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeMint.PreparedNativeResultMismatch();
        }
    }
}

