    error InvalidConservationTier(bytes32 tier);
    error ConservationTierAlreadyDeclared(uint256 collectionId);
    error ConservationTierAfterFirstMint(uint256 collectionId);

    function recordConservationTier(uint256 collectionId, bytes32 tier) external;
    function declaredConservationTier(uint256 collectionId) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Global live supply and current allocation frontiers.
interface IStreamCoreEnumeration {
    /// @notice Returns the live ERC-721 supply, excluding prepared and burned tokens.
    function totalSupply() external view returns (uint256);

    /// @notice Returns the token allocation high-water mark; incident-aborted IDs stay consumed.
    function lastAllocatedTokenId() external view returns (uint256);

    /// @notice Returns the highest collection identifier allocated by Core.
    function lastAllocatedCollectionId() external view returns (uint256);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Raise-only gas budgets for bounded Core external calls.
interface IStreamCoreGasParameters {
    event GasParameterUpdated(
        uint16 schemaVersion,
        bytes32 indexed parameterId,
        address indexed host,
        bytes32 indexed actionId,
        uint256 oldValue,
        uint256 newValue,
        uint256 floor
    );

    /// @notice Returns the configured call budget and its lower bound in gas units.
    /// @param parameterId Domain-defined identifier for the bounded external call.
    /// @return value Current call budget in gas units.
    /// @return floor Permanent lower bound in gas units.
    /// @return failureClass Protocol failure-behavior classification for this call.
    /// @return revision Monotonic configuration revision.
    function gasParameterInfo(bytes32 parameterId)
        external
        view
        returns (uint256 value, uint256 floor, uint8 failureClass, uint64 revision);

    /// @notice Raises a governed external-call budget without lowering its current value or floor.
    /// @dev Requires the exact governed transition; callers cannot use this to lower a budget.
    /// @param newValue Requested call budget in gas units.
    function raiseGasParameter(bytes32 parameterId, uint256 newValue) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Permanent token-to-collection identity and lifecycle reads.
interface IStreamCoreIdentity {
    /// @notice Returns the permanent collection mapping, serial, and burn flag for a token.
    function tokenCollectionIdentity(uint256 tokenId)
        external
        view
        returns (bool mappingExists, uint256 collectionId, uint256 collectionSerial, bool burned);

    /// @notice Returns UNKNOWN=0, PREPARED_INCOMPLETE=1, MINTED=2, or BURNED=3.
    function tokenLifecycle(uint256 tokenId) external view returns (uint8 lifecycle);

    /// @notice Returns the entropy coordinator bound at mint completion, or zero before completion.
    function coordinatorAtMint(uint256 tokenId) external view returns (address);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Authorized metadata invalidation events emitted from Core.
interface IStreamCoreMetadataEmitters {
    event MetadataUpdate(uint256 tokenId);
    event BatchMetadataUpdate(uint256 fromTokenId, uint256 toTokenId);

    event StreamMetadataRefresh(
        uint16 schemaVersion,
        bytes32 indexed reasonHash,
        uint256 indexed fromTokenId,
        uint256 indexed toTokenId
    );

    /// @notice Emits a token metadata invalidation from an authorized metadata component.
    function emitMetadataUpdate(uint256 tokenId, bytes32 reasonHash) external;

    /// @notice Emits metadata invalidation for an inclusive token identifier range.
    function emitBatchMetadataUpdate(uint256 fromTokenId, uint256 toTokenId, bytes32 reasonHash)
        external;

    /// @notice Emits the collection-level ERC-7572 invalidation from an authorized component.
    function emitContractURIUpdated() external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamCoreTypes.sol";

/// @notice Manager-only token allocation, prepared mint lifecycle, and token data.
interface IStreamCoreMint {
    event TokenCollectionRegistered(
        uint16 schemaVersion,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        uint256 collectionSerial
    );

    event TokenCollectionRegistrationReverted(
        uint16 schemaVersion, uint256 indexed tokenId, uint256 indexed collectionId
    );

    /// @notice Allocates and safely mints a token for the installed mint manager.
    /// @dev Only the installed manager may call; receiver rejection rolls back the entire mint.
    /// @param collectionId Existing collection receiving the new token.
    /// @param initialRecipient Address receiving the ERC-721 token and its safe-receiver callback.
    /// @param tokenData_ Artwork bytes whose exact encoding is committed by tokenDataHash.
    /// @param tokenDataHash keccak256 of tokenData_.
    /// @param mintCommitment Per-token commitment passed to the entropy registration boundary.
    /// @return tokenId Globally allocated token identifier.
    /// @return collectionSerial Collection-local serial assigned to this token.
    function mintFromManager(
        uint256 collectionId,
        address initialRecipient,
        bytes calldata tokenData_,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    ) external returns (uint256 tokenId, uint256 collectionSerial);

    /// @notice Reserves the singleton prepared token without completing its ERC-721 mint.
    /// @dev Only the installed manager may call; at most one prepared token exists at a time.
    /// @param operationId Nonzero identity repeated at completion or by a replacement manager during abort.
    function prepareMintFromManager(
        uint256 collectionId,
        bytes calldata tokenData_,
        bytes32 tokenDataHash,
        bytes32 operationId
    ) external returns (uint256 tokenId, uint256 collectionSerial);

    /// @notice Completes the manager operation that owns the prepared token.
    /// @dev The caller, tokenId, and operationId must match the pending preparation.
    /// @param initialRecipient Address receiving the completed token and safe-receiver callback.
    /// @param mintCommitment Per-token commitment supplied at completion.
    function completePreparedMintFromManager(
        uint256 tokenId,
        address initialRecipient,
        bytes32 operationId,
        bytes32 mintCommitment
    ) external;

    /// @notice Aborts a pending preparation through the installed replacement manager.
    /// @dev The installed caller must differ from the preparing manager. The exact
    ///      token/operation match is required; abort removes its identity/data and
    ///      rewinds the global token and collection serial allocation frontiers.
    function abortPreparedMintFromManager(uint256 tokenId, bytes32 operationId) external;

    /// @notice Returns the public pending-operation record for a token.
    function preparedMint(uint256 tokenId) external view returns (StreamPreparedMintRecord memory);

    /// @notice Returns the singleton pending token identifier, or zero when none exists.
    function pendingPreparedMintTokenId() external view returns (uint256 tokenId);

    /// @notice Returns the token artwork data stored by the mint operation.
    function tokenData(uint256 tokenId) external view returns (bytes memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Governed satellite pointers and their verified registry commitments.
interface IStreamCorePointers {
    event CoreSatellitePointerUpdated(
        uint16 schemaVersion,
        bytes32 indexed pointerType,
        bytes32 indexed actionId,
        address indexed newTarget,
        address oldTarget
    );

    event CoreSatellitePointerFrozen(
        uint16 schemaVersion,
        bytes32 indexed pointerType,
        bytes32 indexed actionId,
        address target,
        bytes32 manifestHash
    );

    /// @notice Returns the stored target, registry commitments, freeze state, and revision.
    function getSatellitePointer(bytes32 pointerType)
        external
        view
        returns (
            address target,
            bytes32 codeHash,
            bool frozen,
            bytes32 moduleType,
            bytes4 interfaceId,
            address registry,
            uint8 registryStatus,
            bytes32 moduleManifestHash,
            bytes32 deploymentManifestHash,
            uint64 revision
        );

    /// @notice Replaces an unfrozen satellite after registry and governance-transition checks.
    function updateSatellitePointer(bytes32 pointerType, address newTarget) external;

    /// @notice Permanently freezes an installed satellite pointer through terminal governance.
    function freezeSatellitePointer(bytes32 pointerType) external;
}

